UPDATE "materials" SET "content_payload" = "content_payload" || '"id":"p-019","href":"Text/p-019.xhtml","text":"硝子の塔の殺人\n\nエピローグ\n\n「兄さん、おはよう。郵便、取ってきたよ」\n\n　妹の一条美香が、杖をつきながらふらふらとリビングに入ってくる。\n\n「おい、大丈夫か。一人で歩き回るなって、いつも言ってるだろ」\n\n　朝食のトーストを齧っていた遊馬は、妹を支えようと慌てて立ち上がろうとする。\n\n「大丈夫だってば。リハビリの先生からも、自分で歩いていいってお墨付きもらってるって言ったじゃない。兄さん、過保護すぎなんだよ。そのせいで、私の社会復帰が遅れたらどうするつもり？」\n\n　辛辣な言葉に、遊馬は「分かったよ」と口をへの字にゆがめると、テーブルの上に置いてあるスマートフォンの画面に視線を落とす。\n\n「なに？　また硝子館のニュース調べてるの？　もう大して新しい情報なんてないでしょ」\n\n　美香が呆れ声で言った。\n\n　ガラスの尖塔で起きた惨劇から、すでに半年以上が経過していた。あの日、月夜によって外に運び出された遊馬は、すぐに九流間たちに発見され、救出された。\n\n　吹雪の中、遊馬たちは駐車場に残っていた車の暖房を使用することで、なんとか凍えずに夜を過ごすことができた。\n\n　翌朝になり、前日の吹雪が嘘のように晴れ上がると、一台のワゴン車が山道をのぼってきた。夢読と連絡が途絶えたことを心配してやってきた、芸能事務所のマネージャーだった。そのワゴン車に乗せてもらって下山した遊馬たちは、すぐに警察に通報をした。\n\n　地元の名士であり、世界的にも有名な科学者でもある神津島が殺されたということで、地元警察は大量の捜査員を導入して、犯人である月夜の行方を追った。しかし、彼女を逮捕することはおろか、その足跡さえも摑むことはできなかった。\n\n　最終的に長野県警は、あの吹雪の中、碧月夜は山で遭難し命を落としたと結論づけ、容疑者死亡として書類送検することで強引に事件に幕を引いた。\n\n　奇妙な館で名探偵が起こした連続殺人事件に、マスコミは一時、大いに盛り上がった。しかし、犯人は死亡したものと思われると公式発表が出され、さらに遊馬をはじめとした関係者が一様に硬く口を閉ざしたため、やがて硝子館で起きた惨劇は世間から忘れ去られていった。\n\n　幸運だったのは、遊馬が神津島の毒殺を企んだということを、九流間たちが警察に伝えなかったことだ。おかげで遊馬は運悪く事件に巻き込まれた一人として扱われ、厳しい取り調べを受けることもなかった。\n\n　神津島の死によって販売差し止め訴訟は中止となり、ＡＬＳの新薬は無事に承認されて、美香はそれを内服し続けることができている。おかげで、さらなる筋力の低下は抑えられ、リハビリのかいもあって、最近は杖を使ってわずかな距離なら歩けるまでに回復していた。介護の必要もほとんどなくなったので、遊馬は先月から近くの総合病院に非常勤医師としての勤務をはじめていた。\n\n『硝子の塔の殺人』は終わり、そして自分は新しい日常を生きている。しかしこの半年、遊馬の心の隅にはずっと疑問がくすぶっていた。\n\n　本当に、碧月夜は蝶ヶ岳で命を落としたのだろうか？\n\n　たしかにあの吹雪のなか、徒歩で雪山に入って助かるはずはない。けれど、あの美しい名犯人がそう簡単に死ぬとは思えなかった。\n\n　神津島太郎は慎重な男だった。自らのシナリオの中で街との連絡手段を絶ち、車をパンクさせた彼は、緊急事態のためになにか備えをしていたのではないだろうか。\n\n　例えばその気になったら自分だけでも街におりられるよう、森の中にジェットスキーを隠していたり……。\n\n　考えてもしかたないか。遊馬は首を振ると、再びトーストにかじりつく。たとえ生きていたとしても、彼女と会うことは二度とない。一度分かたれた二人の道が、もはや交わることはないのだから。\n\n　さて、そろそろ出ないと外来に間に合わないな。遊馬は残っていたトーストを口に押し込むと、牛乳で胃に流し込む。\n\n　立ち上がろうとした瞬間、美香が「はい」と葉書を差し出してきた。\n\n「なんだ、これ？」\n\n「よくわかんないけど、兄さん宛てだよ」\n\n　受け取った葉書の表には、『一条遊馬君』という文字があった。差出人の名前はない。\n\n　いったい誰からだ？　普通、宛名は『様』をつけるだろ。\n\n　そんなことを考えながら葉書をめくった遊馬は、大きく目を見開く。裏には美しい絵が描かれていた。\n\n　星で満たされた紺碧の夜空に、満月が輝いている絵。\n\n　そこには流麗な筆記体で、『Godspeed you, my dear Watson』と記されていた。\n\n「なにそれ、きれいな青い月夜の絵葉書だね。どんな意味？」\n\n「……『君の旅路に幸あれ　親愛なるワトソン君』だな」\n\n　遊馬は細めた目で、絵葉書のメッセージを眺める。\n\n「それくらいの英語、分かるよ。ワトソン君って、シャーロック・ホームズに出てくる人でしょ。なんでそんなメッセージが書かれているのか訊いているの。やっぱり、ミステリオタク関係の友達？」\n\n　美香は杖をテーブルに立てかけると、椅子に腰かけた。\n\n「オタクって言うな。マニアだよ。ミステリマニア」\n\n「同じようなものじゃん。で、その人とどんな関係なの？」\n\n「相棒だよ。いや、元相棒かな」\n\n「相棒って、もしかして恋人ってこと!?　え、いつの間に？　私にも紹介してよ」\n\n　美香の目が好奇心で輝く。遊馬は苦笑して席を立った。\n\n「元って言っただろ。もう、彼女と会うことはないよ」\n\n「なんだ、別れたのか。つまんないの」\n\n　後頭部で両手を組む美香を横目に、遊馬は絵葉書に視線を落とす。\n\n　そう、月夜にはもう自分は必要ない。モリアーティが欲するのはワトソンではなく、最強のライバルであるシャーロック・ホームズだ。\n\n　本当なら、この絵葉書は警察に届けるべきなのかもしれない。けれど、そうするつもりはなかった。\n\n　彼女が生きていると知ったとしても、警察が逮捕できるとはとても思えない。\n\n　碧月夜を追い詰められるのは、彼女が長年求め続けてきた『名探偵』だけだ。\n\n　名犯人、碧月夜。\n\n　彼女はこれからも、ともにライヘンバッハの滝に飛び込んでくれる名探偵を探し続けるのだろう。\n\n　その願いが叶って欲しいと思っているのか、遊馬自身にもよく分からなかった。\n\n「とりあえず、君の旅路にも幸運があることを祈っているよ。……月夜」\n\n　遊馬は小さく囁くと、絵葉書をジャケットの内ポケットにしまい、玄関に向かう。\n\n「それじゃあ、行ってくるよ」\n\n　玄関扉を開けてマンションの外廊下に出ると、「行ってらっしゃい、兄さん」という声が追いかけてきた。\n\n　初夏の風が吹き抜けていく。\n\n　新緑の香りがする空気を、遊馬は胸いっぱいに吸い込んだ。","title":"エピローグ"},{"id":"p-020","href":"Text/p-020.xhtml","text":"硝子の塔の殺人\n\n『硝子の塔の殺人』刊行に寄せて\n\n島田荘司\n\n　時代が平成に入り、令和にかかるまで、日本の推理文壇を、全員二十代という書き手たちが支える、世界でも珍しい現象があった。当『硝子の塔の殺人』は、「新本格」と呼ばれたこの特殊な時代を令和の上空から俯瞰し、丹念に総括し、ジャンルの作法を完璧に使いこなして、ブーム終幕に、誰も予想しなかった最高作を産み落として見せた、これもまた、なかなか世にない事件と思う。\n\n　クローズドサークル、突出してユニークな建築物、内部に集合した怪しげな住人たち、彼ら彼女らの、ある傾向をともなう発言、立ち居振る舞い、前段での正直な情報開示と伏線、それらを駒のように動かして浮かばせる緻密な論理性、さらには、一度終演と見せて実は満足していず、裏面に隠した真の論理進行を、これからが本領とばかりに開陳する終盤のどんでん返し、メタ発想の理解と、その自在な活用――。\n\n　すべては「新本格」作法の完璧な具現で、作者の膨大なジャンル作の読み込みが、たびたび教養として示される。一流大学出身者たちらしい難解な理念のアピール、これらへの理解と把握には、医師としての知性も、時に知識も活用されていて、この力作の設計図は、おそらくは知的操作で、方程式を組むようにして机上で考案されたと推察する。本格流儀へのまがいものでない傾倒が、平成が遠のいた今、思いがけず完全なかたちで示されて、その意味でも多く愛好家の度肝を抜くことになろう。\n\n　もっとも筆者は、作者の本格傾倒は知っていて、いずれ本物の本格を書いてくれるから、まあ見ていて欲しいと周囲に言い続けたから、今当作が現れたことに、この上のない満足感を得ている。彼が福ミスに現れたおり、受賞作「レゾン・デートル」を前にして、冒険小説の書き手の混入と早とちりして逃げ腰になったり、距離を取ろうとした当時の出版関係者は、これで自身の不明を恥じなくてはならないだろう。\n\n　この作の内部に、日本の新本格ブームに火をつけたのは島田荘司であり、薪をくべたのは綾辻行人だと解説する一節があるが、そういう二人がこの新作の帯に名を連ね、そして当の知念実希人が、特筆すべきこのミステリー史の一時代に終止符を刻むべく、渾身の力作を世に問うとなれば、これはまたうまく時代が廻ったものと、創作の女神の差配を感じる。\n\n　知念氏自身、これから新しい歩みを踏み出すだろうが、新本格時代を担った多くの才能たちも、これをきりにして、年月を重ねて熟した筆と思想を携え、さらに先の新世紀ミステリーを切り拓かんとする決意を、自覚することだろう。\n\n　この秀作は、フィールドを埋めた日本の書き手たちに、ある踏ん切りをもたらす力を秘めている。わが「本格ミステリー」こそは、アングロサクソンをはじめとする世界のどの才能の真似でもなく、そして中台韓、あるいはタイ、ヴェトナム、インドネシアの才能を牽引するアジアの先導車を自覚させるべく、今この優れた作を、知念氏に運ばせたとぼくは感じている。われわれはここに時代の意志を読み取り、過去の達成を胸にたたんで、新たな前進を開始しなくてはならない。\n\n二〇二一年六月三日","title":"『硝子の塔の殺人』刊行に寄せて"},{"id":"p-021","href":"Text/p-021.xhtml","text":"硝子の塔の殺人\n\n初出\n\n「アップルブックス」配信\n\n二〇二一年六月から七月まで連載。\n\n単行本化にあたり、加筆、修正を行いました。","title":"硝子の塔の殺人"},{"id":"p-022","href":"Text/p-022.xhtml","text":"硝子の塔の殺人\n\n本作はフィクションです。\n\n実在の個人、団体、事件とは一切関係ありません。（編集部）\n\n装丁／川谷康久　装画／青依青　図版監修／天工舎 安井俊夫　図版／ラッシュ","title":"硝子の塔の殺人"},{"id":"p-author","href":"Text/p-author.xhtml","text":"硝子の塔の殺人\n\n［著者略歴］\n\n知念実希人（ちねん・みきと）\n\n１９７８年、沖縄県生まれ。東京都在住。東京慈恵会医科大学卒、日本内科学会認定医。２０１１年、第４回島田荘司選ばらのまち福山ミステリー文学新人賞を『レゾン・デートル』で受賞。12年、同作を改題、『誰がための刃』で作家デビュー（19年『レゾンデートル』として文庫化）。「天久鷹央」シリーズが人気を博し、15年『仮面病棟』が啓文堂文庫大賞を受賞、ベストセラーに。『崩れる脳を抱きしめて』『ひとつむぎの手』『ムゲンのｉ（上・下）』で、18年、19年、20年本屋大賞連続ノミネート。『優しい死神の飼い方』『時限病棟』『リアルフェイス』『レフトハンド・ブラザーフッド』『誘拐遊戯』『十字架のカルテ』『傷痕のメッセージ』など著書多数。今もっとも多くの読者に支持される、最注目のミステリー作家。","title":"硝子の塔の殺人"},{"id":"p-colophon","href":"Text/p-colophon.xhtml","text":"硝子の塔の殺人\n\n硝子の塔の殺人\n\n電子書籍版　２０２１年７月30日発行\n\n著　者　知念実希人\n\n発行者　岩野裕一\n\n発行所　株式会社実業之日本社\n\n　　　　〒１０７－００６２\n\n　　　　東京都港区南青山５－４－30　CoSTUME NATIONAL Aoyama Complex ２Ｆ\n\n　　　　電話　０３－６８０９－０４９５\n\nＥＰＵＢ制作　ＤＮＰメディア・アート\n\n©Mikito Chinen 2021\n\n●本書の内容を無断で複製・複写・放送・データ送信などすることは、かたくお断りします。\n\n●本書は二〇二一年八月、弊社より刊行されました。\n\n●本電子書籍は二〇二一年八月一〇日発行の初版第一刷を底本としています。","title":"硝子の塔の殺人"}],"fileName":"[知念 実希人] 硝子の塔の殺人 (1).epub","language":"ja","sourceKind":"EPUB","description":null}' WHERE "id" = 'c7311f6b-58f5-4b3b-bb3f-f15ac3625c67' AND changes() = 1;

INSERT OR IGNORE INTO "materials" ("id", "type", "title", "chapter_name", "content_payload", "metadata", "created_at", "updated_at") VALUES
('92b18576-ef9d-4d1a-ae54-13e9f1fabb55', 'SPEAKING', '20260505 石油と休みの心配', '20260505 石油と休みの心配', '{"audioUrl":"/audios/shadowing/天声人语/2026/1777982917491-20260505.mp3","audioFile":"/audios/shadowing/天声人语/2026/1777982917491-20260505.mp3","dialogues":[{"id":1,"end":1.16,"text":"天声人語","start":0,"stableId":"256fb32c-8c9a-406f-b7fd-cb236b1922b4","sequenceId":1},{"id":2,"end":3.65,"text":"ゴールデンウィーク（ＧＷ）も終わりに近づいた。","start":1.3,"stableId":"29955a11-1ab8-4eaf-8533-1a9a422db8db","sequenceId":2},{"id":3,"end":7.4,"text":"不透明なイラン情勢で原油高が続くとみて、","start":4.14,"stableId":"c4c18a98-8bee-4143-a02c-efa693f42a8e","sequenceId":3},{"id":4,"end":10.3,"text":"駆け込みで旅行に出た人も多くいたらしい","start":7.45,"stableId":"cd835622-6eac-4b73-9786-610dc6b9aff8","sequenceId":4},{"id":5,"end":15.12,"text":"実際、これから空の旅は、だいぶ高くなりそうだ。","start":10.98,"stableId":"5da4bcec-45e5-42b9-a8a5-060eb0f2ac8c","sequenceId":5},{"id":6,"end":22.07,"text":"日本航空と全日空は、５月から国際線運賃に上乗せする燃油サーチャージを引き上げた。","start":15.62,"stableId":"ab92cbe7-f1b0-4da6-b28b-059b36a0bc92","sequenceId":6},{"id":7,"end":25.4,"text":"国内線でも導入が検討されている。","start":22.54,"stableId":"666a3eb8-cf49-45ab-b45d-53a7b6bcc5ee","sequenceId":7},{"id":8,"end":28.81,"text":"もっとも、飛んでいるだけいいかもしれない。","start":25.87,"stableId":"6c949dce-f06e-47a7-a727-c54204ecb232","sequenceId":8},{"id":9,"end":32.94,"text":"米国では傾いていた航空会社が経営破綻した。","start":29.25,"stableId":"848d4266-45f1-44bf-ab7c-186cb0d86161","sequenceId":9},{"id":10,"end":40.2,"text":"日常生活がすでに大きく変化しているのが、中東への石油依存度が高いアジアの国々だ。","start":33.62,"stableId":"eeb23920-bea5-44b7-8e47-06d41e3fccd9","sequenceId":10},{"id":11,"end":46.37,"text":"ベトナムは国民に外出を控え、車の代わりに自転車などを利用するよう求めた。","start":40.67,"stableId":"a8f42bc6-ca04-4dcf-aed6-506fea7e8e2c","sequenceId":11},{"id":12,"end":51.48,"text":"フィリピンは、公務員に最低週１回の在宅勤務を命じた。","start":46.89,"stableId":"e038afd7-9ab2-493f-b3af-d6e05cb727de","sequenceId":12},{"id":13,"end":56.26,"text":"いつまで続くかわからないこの状況を、どうやって乗り切るか。","start":51.97,"stableId":"c16e4526-1370-4bed-acf3-5d20c448bfb4","sequenceId":13},{"id":14,"end":61.4,"text":"国際エネルギー機関（ＩＥＡ）は、個人や企業に対して具体案を示した。","start":56.71,"stableId":"c9984df2-0a4e-4705-b02a-dafc353d9e67","sequenceId":14},{"id":15,"end":68.62,"text":"航空機の利用自粛、公共交通の利用、高速道路の減速、車の乗り合い。","start":61.87,"stableId":"ec6b8c9e-6e41-4ec0-8142-44a9da743028","sequenceId":15},{"id":16,"end":72.4,"text":"さらには、料理に電気を使うことも勧める。","start":69.08,"stableId":"9ed61356-6bcf-47a9-a511-875f038358e3","sequenceId":16},{"id":17,"end":77.77,"text":"こうして世界を見渡すと日本は悠長にすぎやしないかと心配になってくる。","start":72.88,"stableId":"f517c568-dc0a-4043-979a-a6383299bfc0","sequenceId":17},{"id":18,"end":81.43,"text":"政府は国民への節約要請は否定している。","start":78.24,"stableId":"fce079ad-b103-4dab-9724-2138f820a6c6","sequenceId":18},{"id":19,"end":88.25,"text":"だが、サプライチェーンの現場では石油製品の大幅な値上げや新規受注の停止も起きている。","start":81.89,"stableId":"183d353d-aead-41a8-b968-aa5f53be9af7","sequenceId":19},{"id":20,"end":93.12,"text":"それでも、政府から聞こえてくるのは心配ないという声だけだ。","start":88.73,"stableId":"647fc036-4ecd-478a-b601-c1e903726924","sequenceId":20},{"id":21,"end":101.31,"text":"海外では在宅勤務を推奨することで、車通勤で生じる石油の消費と負担を減らすべきだとの声も上がる。","start":93.58,"stableId":"a5091af5-3307-4bdd-9e45-fc4a03e96590","sequenceId":21},{"id":22,"end":104.11,"text":"ＧＷの次は夏休み。","start":101.77,"stableId":"c2a3299a-32d4-40fd-9fd7-e88f7ac2a646","sequenceId":22},{"id":23,"end":107.97,"text":"気兼ねなく移動できる休みは、いつ来るだろう。","start":104.62,"stableId":"a98614d1-9e67-4142-8b2b-86a6bf27eac7","sequenceId":23}]}', NULL, '2026-05-05T03:08:37.591+00:00', '2026-08-10T16:47:29.229+00:00'),
('b360ed6d-a963-4911-8069-d190d13d7ede', 'SPEAKING', 'Section8', 'Section8', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit2/Unit02Section08.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit2/Unit02Section08.mp3","dialogues":[{"id":441,"end":4.92,"text":"1、どこ行こうか？","start":2.13,"sequenceId":1},{"id":442,"end":6.87,"text":"ボーリングに行きたいなー。","start":4.97,"sequenceId":2},{"id":443,"end":10.71,"text":"2、今夜飲みに行かない？","start":7.81,"sequenceId":3},{"id":444,"end":14.26,"text":"今夜か〜、ちょっとさびしいかも。","start":10.76,"sequenceId":4},{"id":445,"end":18.86,"text":"3、最近、暑くなってきたね。","start":15.51,"sequenceId":5},{"id":446,"end":20.72,"text":"もうじき夏が来るね。","start":18.91,"sequenceId":6},{"id":447,"end":24.5,"text":"4、ピーナッツ食べられる？","start":21.58,"sequenceId":7},{"id":448,"end":26.36,"text":"うん、大丈夫だよ。","start":24.55,"sequenceId":8},{"id":449,"end":32.32,"text":"5、すみません、もう少しゆっくり話してください。","start":27.87,"sequenceId":9},{"id":450,"end":34.95,"text":"あ、はい、わかりました。","start":32.37,"sequenceId":10},{"id":451,"end":40.1,"text":"6、今週中にこの資料作らなくちゃ。","start":36.13,"sequenceId":11},{"id":452,"end":41.25,"text":"がんばって！","start":40.15,"sequenceId":12},{"id":453,"end":45.91,"text":"7、ケーキ作ったことありますか？","start":42.32,"sequenceId":13},{"id":454,"end":49.5,"text":"はい、クリスマスはいつも自分で作るんですよ。","start":45.96,"sequenceId":14},{"id":455,"end":54.84,"text":"8、水曜日にパーティーをしようと思っています。","start":50.6,"sequenceId":15},{"id":456,"end":56.01,"text":"来てくださいね。","start":54.9,"sequenceId":16},{"id":457,"end":58.74,"text":"はい！ 他にはだれが行きますか？","start":56.06,"sequenceId":17},{"id":458,"end":62.63,"text":"9、早く行こう！","start":59.97,"sequenceId":18},{"id":459,"end":63.88,"text":"ちょっと待って！","start":62.68,"sequenceId":19},{"id":460,"end":68.37,"text":"10、かっこいい、その携帯！","start":65.12,"sequenceId":20},{"id":461,"end":69.46,"text":"え、ありがとう。","start":68.42,"sequenceId":21},{"id":462,"end":71.57,"text":"昨日買ったばっかりなんだ。","start":69.51,"sequenceId":22}]}', '{}', '2026-04-01T15:03:14.000+00:00', '2026-04-08T00:32:35.637+00:00'),
('33e2209d-b1ae-4128-b772-4743dd8e0325', 'SPEAKING', 'Lesson7', 'Lesson7', '{"audioUrl":"/audios/shadowing/新概念英语第一册/Unit1/007008-Are-You-a-Teacher.mp3","audioFile":"/audios/shadowing/新概念英语第一册/Unit1/007008-Are-You-a-Teacher.mp3","dialogues":[{"id":817,"end":4.99,"text":"Lesson 7 Are you a teacher?","start":0.47,"sequenceId":1},{"id":818,"end":10.23,"text":"Listen to the tape then answer this question.","start":5.93,"sequenceId":2},{"id":819,"end":13.57,"text":"What is Robert''s job?","start":10.88,"sequenceId":3},{"id":820,"end":17.81,"text":"I am a new student.","start":15.17,"sequenceId":4},{"id":821,"end":20.25,"text":"My name''s Robert.","start":17.93,"sequenceId":5},{"id":822,"end":22.45,"text":"Nice to meet you.","start":20.54,"sequenceId":6},{"id":823,"end":24.64,"text":"My name''s Sophie.","start":22.5,"sequenceId":7},{"id":824,"end":27.68,"text":"Are you French?","start":25.65,"sequenceId":8},{"id":825,"end":29.72,"text":"Yes I am.","start":27.73,"sequenceId":9},{"id":826,"end":32.72,"text":"Are you French too?","start":30.32,"sequenceId":10},{"id":827,"end":36.13,"text":"No I am not.","start":33.14,"sequenceId":11},{"id":828,"end":39.23,"text":"What nationality are you?","start":36.45,"sequenceId":12},{"id":829,"end":42.24,"text":"I''m Italian.","start":40.01,"sequenceId":13},{"id":830,"end":45.89,"text":"Are you a teacher?","start":43.47,"sequenceId":14},{"id":831,"end":48.1,"text":"No I''m not.","start":45.94,"sequenceId":15},{"id":832,"end":50.37,"text":"What''s your job?","start":48.37,"sequenceId":16},{"id":833,"end":53.76,"text":"I''m a keyboard operator.","start":50.6,"sequenceId":17},{"id":834,"end":55.82,"text":"What''s your job?","start":54.09,"sequenceId":18},{"id":835,"end":58.72,"text":"I''m an engineer.","start":56.24,"sequenceId":19}]}', '{}', '2026-04-01T15:03:14.000+00:00', '2026-04-08T00:32:59.019+00:00'),
('d30d79ba-2c50-4b58-aa8f-a1b82f46f07e', 'LISTENING', '問題3-01｜概要理解', NULL, '{"tags":[],"source":"","audioUrl":"/audios/listening/jlpt/n1/2025-07/2025-07-N1-P03-Q01.mp3","language":"","audioFile":"/audios/listening/jlpt/n1/2025-07/2025-07-N1-P03-Q01.mp3","dialogues":[{"id":1,"end":5.56,"note":"","text":"1番 自然公園の入り口でガイドが話しています。","start":0.09,"favorite":false,"stableId":"135fc141-f24f-4431-89ae-5ba44b63f768","sequenceId":1},{"id":2,"end":11.71,"note":"","text":"こんにちは、ガイドの森田です。","start":9.1,"favorite":false,"stableId":"00e61569-fe7f-4bb8-b21f-0bdb653d2c10","sequenceId":2},{"id":3,"end":13.21,"note":"","text":"よろしくお願いします。","start":11.76,"favorite":false,"stableId":"814249dd-370d-452c-a89f-63f6ebb59963","sequenceId":3},{"id":4,"end":19.09,"note":"","text":"えー、この自然公園では珍しい動物や植物に出会うことができます。","start":13.5,"favorite":false,"stableId":"eaeb837f-70fb-42f3-9f3f-941e49f503bb","sequenceId":4},{"id":5,"end":23.18,"note":"","text":"特に冬の今の時期は木々の葉が落ちているので、","start":19.41,"favorite":false,"stableId":"d6571af0-025a-483c-aa9a-906d72d697ca","sequenceId":5},{"id":6,"end":25.08,"note":"","text":"野鳥を探しやすいです。","start":23.23,"favorite":false,"stableId":"89a251c6-8774-4165-9b6f-3759a367a5d6","sequenceId":6},{"id":7,"end":26.83,"note":"","text":"散策しながら、","start":25.5,"favorite":false,"stableId":"accac2f4-670a-4e5b-9584-e402a8960a83","sequenceId":7},{"id":8,"end":30.74,"note":"","text":"野生の小鳥たちのさえずりに耳を傾けてみましょう。","start":26.88,"favorite":false,"stableId":"a5980799-7725-4b88-bdc7-ab648f267fbf","sequenceId":8},{"id":9,"end":36.06,"note":"","text":"これから雑木林の中に整備された遊歩道を進みますが、","start":31.44,"favorite":false,"stableId":"013dad86-5f2f-41b1-a677-73c22cfca92e","sequenceId":9},{"id":10,"end":40.26,"note":"","text":"双眼鏡がなくても肉眼で可愛い姿を見つけられます。","start":36.11,"favorite":false,"stableId":"d59c312e-03eb-4b65-b7e7-bc86352ecbe0","sequenceId":10},{"id":11,"end":45.76,"note":"","text":"種類を見分けるには羽や嘴がそれぞれ特徴的なので、","start":40.89,"favorite":false,"stableId":"4afcf939-88d0-4e4f-9480-7b8a3f85fc3a","sequenceId":11},{"id":12,"end":47.74,"note":"","text":"様子を眺めてみてください。","start":45.81,"favorite":false,"stableId":"103a35e6-06ee-4469-a1a5-a3ea0098f35f","sequenceId":12},{"id":13,"end":54.28,"note":"","text":"運が良ければ、保護の対象になっている貴重な野鳥にも巡り会えるかもしれません。","start":48.22,"favorite":false,"stableId":"69787907-5312-4a7d-9647-37470f400917","sequenceId":13},{"id":14,"end":62.79,"note":"","text":"ガイドは何について話していますか。","start":59.56,"favorite":false,"stableId":"1cd6ce9d-6613-4539-bc3f-954df0618a93","sequenceId":14},{"id":15,"end":68.22,"note":"","text":"1 野鳥の観察の楽しみ方","start":64.19,"favorite":false,"stableId":"b82f8862-d512-466d-a9f3-0ff293e08694","sequenceId":15},{"id":16,"end":74.54,"note":"","text":"2 自然保険で育つ植物","start":70.6,"favorite":false,"stableId":"5e76bf30-c254-4353-ad75-b944edabade0","sequenceId":16},{"id":17,"end":81.34,"note":"","text":"3 自然公園を歩く時の注意点","start":77.01,"favorite":false,"stableId":"0368458e-7654-4ba2-a914-87a0b372d5e1","sequenceId":17},{"id":18,"end":87.72,"note":"","text":"4 野鳥の保護の必要性","start":83.86,"favorite":false,"stableId":"eb7afc60-dcec-451b-9281-cfed34f1f3d0","sequenceId":18}],"jlptLevel":"N1","difficulty":"","transcript":"","description":"","jlptSession":"2025-07","sectionTitle":"概要理解","sectionNumber":3,"questionNumber":1,"listeningSectionTitle":"概要理解","questionEntryRequired":false,"listeningSectionNumber":3}', NULL, '2026-08-10T06:15:33.784+00:00', '2026-08-10T06:48:00.986+00:00'),
('dbd5c8ef-f774-478e-9950-ec3566f11674', 'SPEAKING', 'Section2', 'Section2', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit5/Unit05Section02.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit5/Unit05Section02.mp3","dialogues":[{"id":1185,"end":5.84,"text":"1、先生、ご無沙汰しています。","start":1.63,"sequenceId":1},{"id":1186,"end":8.9,"text":"あ、山田君。最近どうですか？","start":5.89,"sequenceId":2},{"id":1187,"end":11.19,"text":"ええ、なんとかやってます。","start":9.01,"sequenceId":3},{"id":1188,"end":16.82,"text":"2、田中さん、カゼをこじらせて入院したそうですよ。","start":12.32,"sequenceId":4},{"id":1189,"end":19.63,"text":"えっ。じゃ、お見舞いにいかなくちゃ。","start":16.87,"sequenceId":5},{"id":1190,"end":21.5,"text":"行くなら一緒に行きませんか？","start":19.68,"sequenceId":6},{"id":1191,"end":24.96,"text":"3、どう？","start":22.6,"sequenceId":7},{"id":1192,"end":26.65,"text":"今日、焼き肉に行かない？","start":25.01,"sequenceId":8},{"id":1193,"end":28.69,"text":"焼き肉か〜、","start":26.7,"sequenceId":9},{"id":1194,"end":33.08,"text":"おととい、食べ放題で、いやっていうほど肉を食べたんですよ。","start":28.74,"sequenceId":10},{"id":1195,"end":35.34,"text":"へ〜、いいなぁ。","start":33.13,"sequenceId":11},{"id":1196,"end":37.18,"text":"じゃ、今日もそこ行かない？","start":35.39,"sequenceId":12},{"id":1197,"end":38.39,"text":"だから！","start":37.23,"sequenceId":13},{"id":1198,"end":43.59,"text":"4、なんだか最近寝ても疲れが取れないんだよねー。","start":38.99,"sequenceId":14},{"id":1199,"end":45.13,"text":"あ、本当？","start":43.64,"sequenceId":15},{"id":1200,"end":46.72,"text":"肩揉んであげようか。","start":45.18,"sequenceId":16},{"id":1201,"end":47.85,"text":"本当？","start":46.77,"sequenceId":17},{"id":1202,"end":48.81,"text":"いいの？","start":47.9,"sequenceId":18},{"id":1203,"end":55.26,"text":"5、お見舞いに行く時、何を持って行きましょうか？","start":50.71,"sequenceId":19},{"id":1204,"end":56.67,"text":"そうですね、","start":55.31,"sequenceId":20},{"id":1205,"end":59.51,"text":"普通だけど、花にしようか？","start":56.74,"sequenceId":21},{"id":1206,"end":62.45,"text":"ええ、切り花でしたよね。","start":59.87,"sequenceId":22},{"id":1207,"end":69.95,"text":"6、ねー、こんどまたディズニーランドに行こうよ。","start":64.9,"sequenceId":23},{"id":1208,"end":72.62,"text":"え〜。また〜。","start":70,"sequenceId":24},{"id":1209,"end":74.37,"text":"そのうちね。","start":73.02,"sequenceId":25},{"id":1210,"end":76.23,"text":"そのうちっていつ？","start":74.42,"sequenceId":26},{"id":1211,"end":81.4,"text":"7、どこの病院に入院したんですか？","start":77.54,"sequenceId":27},{"id":1212,"end":84.37,"text":"西新宿の大学病院みたいですよ。","start":81.45,"sequenceId":28},{"id":1213,"end":86.28,"text":"あ、そうですか。","start":84.42,"sequenceId":29},{"id":1214,"end":93.59,"text":"8、ねーねー、あのまるい眼鏡をかけてマフラーしている男の人…。","start":87.06,"sequenceId":30},{"id":1215,"end":95.59,"text":"どっかで見たことない？","start":93.98,"sequenceId":31},{"id":1216,"end":97.42,"text":"あー、あの人ね。","start":95.64,"sequenceId":32},{"id":1217,"end":99.84,"text":"隣のコンビニの店長でしょう。","start":97.54,"sequenceId":33},{"id":1218,"end":101.7,"text":"あ、そうだね。","start":100.05,"sequenceId":34},{"id":1219,"end":103.81,"text":"制服じゃないとわかんないね。","start":101.82,"sequenceId":35},{"id":1220,"end":109.36,"text":"9、このへんに100円ショップはありますか？","start":105.63,"sequenceId":36},{"id":1221,"end":112.92,"text":"はい。この道を真っ直ぐ行くと、コンビニがあります。","start":109.41,"sequenceId":37},{"id":1222,"end":114.15,"text":"その隣です。","start":112.97,"sequenceId":38},{"id":1223,"end":116,"text":"まだ、開いていますかね。","start":114.24,"sequenceId":39},{"id":1224,"end":119.57,"text":"ええ、24時間営業だから大丈夫ですよ。","start":116.05,"sequenceId":40},{"id":1225,"end":124.37,"text":"10、最近、出会いがないよね。","start":120.8,"sequenceId":41},{"id":1226,"end":127.24,"text":"うん。合コンしてみる？","start":124.49,"sequenceId":42},{"id":1227,"end":129.79,"text":"まー、だめもとでしてみるか。","start":127.45,"sequenceId":43}]}', '{}', '2026-04-04T22:36:31.930+00:00', '2026-04-08T00:10:44.016+00:00'),
('e274efb5-fd65-40f1-923f-c96998e72096', 'SPEAKING', 'Section7', 'Section7', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit4/Unit04Section07.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit4/Unit04Section07.mp3","dialogues":[{"id":1098,"end":8.16,"text":"1、田中さんの結婚パーティー、いつでしたっけ？","start":3.76,"sequenceId":1},{"id":1099,"end":12.65,"text":"えーと、確か10日の午後3時からです。","start":8.21,"sequenceId":2},{"id":1100,"end":17.96,"text":"2、当日、どんな服を着て行きますか？","start":14.04,"sequenceId":3},{"id":1101,"end":19.91,"text":"平服でいいみたいですよ。","start":18.01,"sequenceId":4},{"id":1102,"end":24.47,"text":"3、プレゼントはどうしますか？","start":21.33,"sequenceId":5},{"id":1103,"end":28.41,"text":"いろいろ考えたけど、お金を包むことにしました。","start":24.53,"sequenceId":6},{"id":1104,"end":35.3,"text":"4、結婚式の時、新郎新婦になんて言えばいいんですか？","start":30.12,"sequenceId":7},{"id":1105,"end":36.84,"text":"そうですね。","start":35.43,"sequenceId":8},{"id":1106,"end":39.04,"text":"「ご結婚おめでとうございます。","start":36.93,"sequenceId":9},{"id":1107,"end":42.13,"text":"お幸せに！」が一般的ですね。","start":39.09,"sequenceId":10},{"id":1108,"end":48.23,"text":"5、26.5センチの皮靴を買いたいんですが。","start":43.56,"sequenceId":11},{"id":1109,"end":49.08,"text":"はい。","start":48.31,"sequenceId":12},{"id":1110,"end":52.36,"text":"それでは、こちらの靴はいかがでしょうか？","start":49.15,"sequenceId":13},{"id":1111,"end":58.11,"text":"6、彼女、目がくりくりしていて、かわいいね。","start":53.46,"sequenceId":14},{"id":1112,"end":61.17,"text":"え、彼女みたいなタイプが好きなの？","start":58.16,"sequenceId":15},{"id":1113,"end":65.63,"text":"7、もう3月だよ。","start":62.58,"sequenceId":16},{"id":1114,"end":67.24,"text":"そこのカレンダーめくって。","start":65.68,"sequenceId":17},{"id":1115,"end":68.83,"text":"うん、わかった。","start":67.29,"sequenceId":18},{"id":1116,"end":73.94,"text":"8、バケツの中の水、捨ててください。","start":69.97,"sequenceId":19},{"id":1117,"end":74.91,"text":"はーい。","start":73.99,"sequenceId":20},{"id":1118,"end":77.01,"text":"じゃ、庭にまいておきます。","start":74.96,"sequenceId":21},{"id":1119,"end":82.29,"text":"9、コンサートのチケット、予約した？","start":78.63,"sequenceId":22},{"id":1120,"end":84.26,"text":"それがだめだったんだ。","start":82.39,"sequenceId":23},{"id":1121,"end":86.87,"text":"チケット、30分で売り切れたらしい。","start":84.31,"sequenceId":24},{"id":1122,"end":92.29,"text":"10、コンサートのチケット、電話予約しておいたから。","start":87.96,"sequenceId":25},{"id":1123,"end":94.97,"text":"じゃー、すぐにお金振り込まなくちゃね。","start":92.34,"sequenceId":26}]}', '{}', '2026-04-03T04:38:43.720+00:00', '2026-04-08T00:10:53.468+00:00'),
('e2d44893-787a-4000-9891-175e73d8711a', 'SPEAKING', 'Section7', 'Section7', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit2/Unit02Section07.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit2/Unit02Section07.mp3","dialogues":[{"id":418,"end":5.19,"text":"1、駅に着いたら、電話して。","start":1.75,"sequenceId":1},{"id":419,"end":6.09,"text":"迎えに行くよ。","start":5.24,"sequenceId":2},{"id":420,"end":6.93,"text":"ありがとう。","start":6.14,"sequenceId":3},{"id":421,"end":7.89,"text":"よろしく！","start":6.98,"sequenceId":4},{"id":422,"end":11.27,"text":"2、お先に失礼します。","start":8.79,"sequenceId":5},{"id":423,"end":12.48,"text":"おつかれさま。","start":11.32,"sequenceId":6},{"id":424,"end":16.24,"text":"3、いい天気だね。","start":13.66,"sequenceId":7},{"id":425,"end":17.78,"text":"どこか行きたいね。","start":16.29,"sequenceId":8},{"id":426,"end":21.51,"text":"4、まだ仕事？","start":19.03,"sequenceId":9},{"id":427,"end":24.51,"text":"うん、今日はまだ終われないんだ。","start":21.56,"sequenceId":10},{"id":428,"end":28.27,"text":"5、今日、何しようか。","start":25.4,"sequenceId":11},{"id":429,"end":30.95,"text":"ピザ食べながら、DVD見ようよ。","start":28.32,"sequenceId":12},{"id":430,"end":36.01,"text":"6、ワールドカップ、どこが勝つと思う？","start":32.08,"sequenceId":13},{"id":431,"end":38.39,"text":"うーん。どこかな。","start":36.06,"sequenceId":14},{"id":432,"end":41.18,"text":"でも日本にがんばってほしいと思うよ。","start":38.55,"sequenceId":15},{"id":433,"end":46.92,"text":"7、すみません、道を教えてもらえませんか？","start":42.81,"sequenceId":16},{"id":434,"end":48.77,"text":"はい、どこですか。","start":46.97,"sequenceId":17},{"id":435,"end":54.04,"text":"8、あ、サイフ忘れちゃった！","start":50.52,"sequenceId":18},{"id":436,"end":55.32,"text":"貸してあげるよ。","start":54.09,"sequenceId":19},{"id":437,"end":59.69,"text":"9、会議が終わったら、電話してください。","start":56.4,"sequenceId":20},{"id":438,"end":60.9,"text":"わかりました。","start":59.74,"sequenceId":21},{"id":439,"end":65.61,"text":"10、昨日行ったレストラン、おいしかったね。","start":62.04,"sequenceId":22},{"id":440,"end":67.96,"text":"うん、とくにデザートがね。","start":65.66,"sequenceId":23}]}', '{}', '2026-04-01T15:03:14.000+00:00', '2026-04-08T00:32:35.637+00:00'),
('e669063b-f8a2-475a-9025-f3e4155f12bb', 'SPEAKING', 'Section2', 'Section2', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit3/Unit03Section02.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit3/Unit03Section02.mp3","dialogues":[{"id":519,"end":5.4,"text":"1、袋にお入れしましょうか？","start":1.81,"sequenceId":1},{"id":520,"end":7.35,"text":"いいえ、そのままで。","start":5.53,"sequenceId":2},{"id":521,"end":12.12,"text":"2、来週、京都から友だちがくるんだ。","start":8.02,"sequenceId":3},{"id":522,"end":13.41,"text":"そうなんだ。","start":12.25,"sequenceId":4},{"id":523,"end":14.55,"text":"楽しみだね。","start":13.46,"sequenceId":5},{"id":524,"end":19.44,"text":"3、お姉ちゃん、今日何時に帰ってくる？","start":15.4,"sequenceId":6},{"id":525,"end":22.5,"text":"うーん。8時ごろになるかな。","start":19.49,"sequenceId":7},{"id":526,"end":27.19,"text":"4、あれ？ 電気がついていますね。","start":23.36,"sequenceId":8},{"id":527,"end":28.58,"text":"本当だ。","start":27.38,"sequenceId":9},{"id":528,"end":30.29,"text":"だれがつけたんでしょうね。","start":28.63,"sequenceId":10},{"id":529,"end":35.28,"text":"5、先生、3級合格しました。","start":31.17,"sequenceId":11},{"id":530,"end":37.19,"text":"えっ！ すごい。","start":35.33,"sequenceId":12},{"id":531,"end":38.29,"text":"おめでとう。","start":37.24,"sequenceId":13},{"id":532,"end":42.55,"text":"6、あれ？ ご飯食べないの？","start":38.78,"sequenceId":14},{"id":533,"end":44.88,"text":"うん、ダイエット中でね。","start":42.71,"sequenceId":15},{"id":534,"end":47.08,"text":"野菜しか食べないようにしてるんだ。","start":44.99,"sequenceId":16},{"id":535,"end":51.36,"text":"7、明日、うかがってもよろしいですか？","start":47.47,"sequenceId":17},{"id":536,"end":53.89,"text":"はい、かまいませんよ。","start":51.81,"sequenceId":18},{"id":537,"end":59.72,"text":"8、昨日、東京駅で事件があったらしいですね。","start":54.93,"sequenceId":19},{"id":538,"end":61.44,"text":"そうらしいですね。","start":59.83,"sequenceId":20},{"id":539,"end":66.93,"text":"9、明日までにレポート、書いてくださいね。","start":62.76,"sequenceId":21},{"id":540,"end":68.9,"text":"はい、大丈夫です。","start":67.2,"sequenceId":22},{"id":541,"end":71.1,"text":"もう90％書いてあります。","start":68.95,"sequenceId":23},{"id":542,"end":74.02,"text":"10、これ何？","start":71.82,"sequenceId":24},{"id":543,"end":75.27,"text":" シャドーイング？","start":74.07,"sequenceId":25},{"id":544,"end":77.44,"text":"これなんのためにしてるの？","start":75.51,"sequenceId":26},{"id":545,"end":80.72,"text":"うん、すらすら話せるようになるんだって。","start":77.57,"sequenceId":27}]}', '{}', '2026-04-01T15:03:14.000+00:00', '2026-04-08T00:11:01.768+00:00'),
('ea45cb1e-7b87-42c7-90a1-1cc6766412db', 'SPEAKING', 'Section4', 'Section4', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit2/Unit02Section04.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit2/Unit02Section04.mp3","dialogues":[{"id":346,"end":5.57,"text":"1、いつも日曜日、何をしているの？","start":1.81,"sequenceId":1},{"id":347,"end":10.94,"text":"うーん、テレビ見たりマンガ読んだり…ゴロゴロしてるよ。","start":5.62,"sequenceId":2},{"id":348,"end":16.53,"text":"2、ねー、このCDなんでこんなに安いんだろう？","start":11.94,"sequenceId":3},{"id":349,"end":18.95,"text":"うん、なんでだろうね。","start":16.58,"sequenceId":4},{"id":350,"end":20.71,"text":"偽物かもね。","start":19.09,"sequenceId":5},{"id":351,"end":24.32,"text":"3、夏休みはどうするの？","start":21.36,"sequenceId":6},{"id":352,"end":26.74,"text":"1人で中国に行くつもりです。","start":24.37,"sequenceId":7},{"id":353,"end":30.64,"text":"4、日本の生活はどう？","start":27.66,"sequenceId":8},{"id":354,"end":31.73,"text":"もうなれた？","start":30.69,"sequenceId":9},{"id":355,"end":35.25,"text":"ええ。生ものも食べられるようになりました。","start":31.78,"sequenceId":10},{"id":356,"end":39.78,"text":"5、あ、リサさん、ひさしぶり。","start":36.37,"sequenceId":11},{"id":357,"end":41.74,"text":"今、何をしているんですか？","start":39.9,"sequenceId":12},{"id":358,"end":43.92,"text":"新宿で英語を教えています。","start":41.79,"sequenceId":13},{"id":359,"end":49.03,"text":"6、学校までどうやって来るんですか？","start":45.27,"sequenceId":14},{"id":360,"end":51.64,"text":"うちから山手線で一本です。","start":49.08,"sequenceId":15},{"id":361,"end":56.52,"text":"7、ねー、そろそろ行きませんか？","start":52.92,"sequenceId":16},{"id":362,"end":58.1,"text":"あ、ちょっと待って。","start":56.57,"sequenceId":17},{"id":363,"end":59.97,"text":"その前にトイレトイレ。","start":58.15,"sequenceId":18},{"id":364,"end":65.06,"text":"8、ねー、もう宿題した？","start":61.16,"sequenceId":19},{"id":365,"end":68.16,"text":"ううん。土日にするつもりだけど。","start":65.11,"sequenceId":20},{"id":366,"end":73.55,"text":"9、鈴木さんはどこに住んでいるの？","start":70.21,"sequenceId":21},{"id":367,"end":75.16,"text":"中野駅のそば。","start":73.6,"sequenceId":22},{"id":368,"end":76.59,"text":"ピーターさんは？","start":75.25,"sequenceId":23},{"id":369,"end":81.71,"text":"10、知らない人についていっちゃだめだよ。","start":78.04,"sequenceId":24},{"id":370,"end":82.79,"text":"はい…。","start":81.76,"sequenceId":25}]}', '{}', '2026-04-01T15:03:14.000+00:00', '2026-04-08T00:32:35.637+00:00'),
('f0c907cb-592b-45a0-86aa-b8cfeb3f6f33', 'SPEAKING', 'Section2', 'Section2', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit4/Unit04Section02.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit4/Unit04Section02.mp3","dialogues":[{"id":1,"end":6.39,"text":"1、すみません。ちょっと手伝ってもらえませんか？","start":1.68,"sequenceId":1},{"id":2,"end":8.29,"text":"ええ、いいですよ。","start":6.44,"sequenceId":2},{"id":3,"end":12.85,"text":"2、はさみとホチキスを借りてもいいですか？","start":8.8,"sequenceId":3},{"id":4,"end":15.37,"text":"はい、ちょっと待ってくださいね。","start":13.04,"sequenceId":4},{"id":5,"end":20.51,"text":"3、最近、何かはまってることある？","start":16.37,"sequenceId":5},{"id":6,"end":22.08,"text":"ヨガかな。","start":20.73,"sequenceId":6},{"id":7,"end":23.35,"text":"あれはいいよ。","start":22.13,"sequenceId":7},{"id":8,"end":28.41,"text":"4、わー、このパソコン、７万円だって。","start":24.32,"sequenceId":8},{"id":9,"end":29.68,"text":"安いよね。","start":28.46,"sequenceId":9},{"id":10,"end":32.42,"text":"うん、絶対これ買いだよね。","start":29.75,"sequenceId":10},{"id":11,"end":37.89,"text":"5、明日、花火大会があんだって。","start":33.85,"sequenceId":11},{"id":12,"end":40.35,"text":"あ、そう。どこで？","start":38.06,"sequenceId":12},{"id":13,"end":45.64,"text":"6、コンビニのお弁当で足りるの？","start":41.91,"sequenceId":13},{"id":14,"end":48.5,"text":"ぜんぜん。すぐおなか減っちゃう。","start":45.69,"sequenceId":14},{"id":15,"end":53.32,"text":"7、このビスケット、百均なんだよ。","start":49.35,"sequenceId":15},{"id":16,"end":54.69,"text":"信じられる？","start":53.37,"sequenceId":16},{"id":17,"end":56.85,"text":"すごい、これ当たり。","start":54.78,"sequenceId":17},{"id":18,"end":58.46,"text":"100円とは思えない！","start":56.9,"sequenceId":18},{"id":19,"end":65.83,"text":"8、飲み会、来週の土曜に変更になったの、知ってる？","start":59.93,"sequenceId":19},{"id":20,"end":68.21,"text":"えー、そうなの？","start":65.88,"sequenceId":20},{"id":21,"end":71.25,"text":"なんだ、今週バイト断ったのに。","start":68.26,"sequenceId":21},{"id":22,"end":75.89,"text":"9、サイズはいかがですか？","start":72.81,"sequenceId":22},{"id":23,"end":78.24,"text":"ええ、ぴったりです。","start":76.32,"sequenceId":23},{"id":24,"end":83.72,"text":"10、あそこの大学、倍率５倍なんだって。","start":78.96,"sequenceId":24},{"id":25,"end":86.8,"text":"まー、だめもとでチャレンジしたら？","start":84.13,"sequenceId":25}]}', '{}', '2026-04-03T01:49:01.864+00:00', '2026-04-08T00:10:53.468+00:00'),
('f2604d89-d8e4-4dd4-ae30-bff221ae7a4c', 'SPEAKING', 'Section2', 'Section2', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit2/Unit02Section02.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit2/Unit02Section02.mp3","dialogues":[{"id":298,"end":5.01,"text":"1、昨日、暑かったね。","start":1.81,"sequenceId":1},{"id":299,"end":9.57,"text":"本当。暑くて暑くて…寝られなかったよ。","start":5.06,"sequenceId":2},{"id":300,"end":14.57,"text":"2、田中さんの彼女ってどの人ですか？","start":10.63,"sequenceId":3},{"id":301,"end":17.07,"text":"ほら、あそこで電話してる人。","start":14.62,"sequenceId":4},{"id":302,"end":21.41,"text":"3、今夜飲みに行きませんか？","start":18.32,"sequenceId":5},{"id":303,"end":22.37,"text":"いいですね。","start":21.46,"sequenceId":6},{"id":304,"end":23.56,"text":"行きましょう。","start":22.42,"sequenceId":7},{"id":305,"end":30.58,"text":"4、ねー、パンを食べるの「を」って、パソコンでどう書くんですか？","start":24.69,"sequenceId":8},{"id":306,"end":32.8,"text":"WOですよ。","start":30.66,"sequenceId":9},{"id":307,"end":35.96,"text":"5、あれ？","start":33.88,"sequenceId":10},{"id":308,"end":37.67,"text":"あんまり食べないねー。","start":36.01,"sequenceId":11},{"id":309,"end":42.39,"text":"うーん、今日はおなかの調子があまり良くないんです。","start":37.72,"sequenceId":12},{"id":310,"end":48.44,"text":"6、あー、新しい言葉がたくさんある…。","start":43.38,"sequenceId":13},{"id":311,"end":51.84,"text":"本当。頭が変になりそう…。","start":48.55,"sequenceId":14},{"id":312,"end":56.84,"text":"7、ずいぶん涼しくなりましたね。","start":53.46,"sequenceId":15},{"id":313,"end":58.08,"text":"そうですね。","start":56.89,"sequenceId":16},{"id":314,"end":61.93,"text":"8、あれ？","start":59.37,"sequenceId":17},{"id":315,"end":63.71,"text":"ここ携帯使えないんだ。","start":61.98,"sequenceId":18},{"id":316,"end":64.4,"text":"うん。","start":63.76,"sequenceId":19},{"id":317,"end":65.76,"text":"地下だからね。","start":64.45,"sequenceId":20},{"id":318,"end":70.45,"text":"9、日本に来てどれぐらいになりますか？","start":66.93,"sequenceId":21},{"id":319,"end":72.38,"text":"2年半になります。","start":70.63,"sequenceId":22},{"id":320,"end":77.19,"text":"10、山田さんはどちらにお住まいですか？","start":73.52,"sequenceId":23},{"id":321,"end":79.07,"text":"この近所に住んでいます。","start":77.28,"sequenceId":24},{"id":322,"end":80.42,"text":"すぐそこです。","start":79.16,"sequenceId":25}]}', '{}', '2026-04-01T15:03:14.000+00:00', '2026-04-08T00:32:35.637+00:00'),
('f371154c-e1a6-4b4c-8a9b-f582c6d76df3', 'SPEAKING', '大学・専門学校入試の面接', '19', '{"audioUrl":"/audios/shadowing/面接編-新・シャドーイング-日本語を話そう/Unit2/19.mp3","audioFile":"/audios/shadowing/面接編-新・シャドーイング-日本語を話そう/Unit2/19.mp3","dialogues":[{"id":1,"end":5.74,"text":"25、ほかの大学も受験しますか。","start":0.76,"sequenceId":1},{"id":2,"end":10.89,"text":"はい。こちらの大学と地球市民大学とを受験しています。","start":6.29,"sequenceId":2},{"id":3,"end":14.99,"text":"どちらも非常に魅力的な大学だと考えています。","start":11.23,"sequenceId":3},{"id":4,"end":21.79,"text":"26、今日の試験はどうでしたか。","start":17.13,"sequenceId":4},{"id":5,"end":25.05,"text":"はい。おおかた良くできたと思います。","start":22.3,"sequenceId":5},{"id":6,"end":28.37,"text":"小論文では時間がギリギリでしたが、","start":25.28,"sequenceId":6},{"id":7,"end":31.18,"text":"伝えたい内容は書けたと思っています。","start":28.42,"sequenceId":7},{"id":8,"end":39.25,"text":"27、では、最後に何か質問があればどうぞ。","start":33.31,"sequenceId":8},{"id":9,"end":45.41,"text":"はい。合格が決まり次第、アパートやアルバイトを探そうと思っているんですが、","start":39.61,"sequenceId":9},{"id":10,"end":48.64,"text":"学校から紹介していただくことはできますか。","start":45.46,"sequenceId":10},{"id":11,"end":57.33,"text":"28、では、そちらから何か質問があればお聞きください。","start":50.74,"sequenceId":11},{"id":12,"end":61.85,"text":"はい。あのー、大学に寮があるようですが、","start":57.9,"sequenceId":12},{"id":13,"end":65.38,"text":"寮に住むにはどういう手続きが必要ですか。","start":61.9,"sequenceId":13},{"id":14,"end":73.07,"text":"29、それでは逆に質問などがあれば受けますが。","start":67.36,"sequenceId":14},{"id":15,"end":77.11,"text":"はい。あの、ご助言いただきたいんですが。","start":73.51,"sequenceId":15},{"id":16,"end":79.61,"text":"もし合格通知をいただいたら、","start":77.31,"sequenceId":16},{"id":17,"end":82.82,"text":"入学までに２ヶ月ぐらい時間がありますが、","start":79.66,"sequenceId":17},{"id":18,"end":85.44,"text":"どんな勉強をしておけばいいでしょうか。","start":82.87,"sequenceId":18}]}', NULL, '2026-04-15T03:07:38.215+00:00', '2026-08-10T16:47:29.209+00:00'),
('f7b1199c-fab5-40ca-90f6-734ae95ffc7c', 'SPEAKING', 'Lesson3', 'Lesson3', '{"audioUrl":"/audios/shadowing/新概念英语第一册/Unit1/003004-Sorry-Sir.mp3","audioFile":"/audios/shadowing/新概念英语第一册/Unit1/003004-Sorry-Sir.mp3","dialogues":[{"id":695,"end":4.62,"text":"Lesson 3 Sorry sir.","start":0.67,"sequenceId":1},{"id":696,"end":10.44,"text":"Listen to the tape then answer this question.","start":5.67,"sequenceId":2},{"id":697,"end":15.22,"text":"Does the man get his umbrella back?","start":11.64,"sequenceId":3},{"id":698,"end":21.11,"text":"My coat and my umbrella please.","start":17.48,"sequenceId":4},{"id":699,"end":24.04,"text":"Here is my ticket.","start":21.94,"sequenceId":5},{"id":700,"end":26.68,"text":"Thank you sir.","start":24.88,"sequenceId":6},{"id":701,"end":28.47,"text":"Number five.","start":26.8,"sequenceId":7},{"id":702,"end":32.66,"text":"Here''s your umbrella and your coat.","start":29.03,"sequenceId":8},{"id":703,"end":37.11,"text":"This is not my umbrella.","start":33.65,"sequenceId":9},{"id":704,"end":39.03,"text":"Sorry sir.","start":37.33,"sequenceId":10},{"id":705,"end":42.03,"text":"Is this your umbrella?","start":39.61,"sequenceId":11},{"id":706,"end":44.65,"text":"No it isn''t.","start":42.5,"sequenceId":12},{"id":707,"end":47.32,"text":"Is this it?","start":45.62,"sequenceId":13},{"id":708,"end":50.14,"text":"Yes it is.","start":47.69,"sequenceId":14},{"id":709,"end":52.89,"text":"Thank you very much.","start":50.47,"sequenceId":15}]}', '{}', '2026-04-01T15:03:14.000+00:00', '2026-04-08T00:32:59.019+00:00'),
('fbe0bd10-84c0-4d57-acae-10b62fd1159d', 'LISTENING', '問題3-04｜概要理解', NULL, '{"tags":[],"source":"","audioUrl":"/audios/listening/jlpt/n1/2025-07/2025-07-N1-P03-Q04.mp3","language":"","audioFile":"/audios/listening/jlpt/n1/2025-07/2025-07-N1-P03-Q04.mp3","dialogues":[{"id":1,"end":6.88,"note":"","text":"4番 ラジオでアナウンサーが家具を作る職人にインタビューしています。","start":0.05,"favorite":false,"stableId":"c18622e0-473c-4535-adb3-0637be3c22fe","sequenceId":1},{"id":2,"end":12.73,"note":"","text":"今日は家具職人の山下さんにお話を伺います。","start":8.46,"favorite":false,"stableId":"1b791da5-ce34-475d-a6c8-432cc88078ef","sequenceId":2},{"id":3,"end":13.94,"note":"","text":"山下です。","start":12.79,"favorite":false,"stableId":"126af635-6599-4f03-b3fc-6e059fd33e58","sequenceId":3},{"id":4,"end":17.18,"note":"","text":"私は家具を手作りで作っています。","start":14.24,"favorite":false,"stableId":"22675cad-7bd2-415d-a945-1b5a741aa5ed","sequenceId":4},{"id":5,"end":21.15,"note":"","text":"木材は時間が経つにつれて変化するので、","start":17.58,"favorite":false,"stableId":"b673b957-fdfd-4fdb-a955-260fb2ff76a4","sequenceId":5},{"id":6,"end":26.73,"note":"","text":"木の家具は年月が経つと色や質感にいい味が出てくるんです。","start":21.2,"favorite":false,"stableId":"9ec5592a-0dcf-405f-8dbe-9e5c569f0c6a","sequenceId":6},{"id":7,"end":31.66,"note":"","text":"私は木材それぞれの特徴を常々勉強し、","start":27.18,"favorite":false,"stableId":"756e75f6-d664-47d8-a496-a76c74f2aae1","sequenceId":7},{"id":8,"end":33.93,"note":"","text":"木材の変化を見越して、","start":31.75,"favorite":false,"stableId":"d02320a5-a617-4a38-bd31-0813ee40b18a","sequenceId":8},{"id":9,"end":37.73,"note":"","text":"最適なものを選ぶことが大切だと思っています。","start":33.98,"favorite":false,"stableId":"4f3bc008-5eda-49ea-8b93-dc7eca443a2b","sequenceId":9},{"id":10,"end":41.36,"note":"","text":"数十年後の色に深みが増し、","start":38.27,"favorite":false,"stableId":"9b21952c-c7e7-456f-a848-b5d7ff394d14","sequenceId":10},{"id":11,"end":47.73,"note":"","text":"木目が様々な美しい模様に変化する姿をイメージし、一つ一つ作っています。","start":41.41,"favorite":false,"stableId":"05cc39e7-fed7-473b-aab2-694a99c537c1","sequenceId":11},{"id":12,"end":57.73,"note":"","text":"家具を作る職人は何について話していますか？","start":53.28,"favorite":false,"stableId":"64eca9bc-9eef-4bcb-835e-75b0dfadca59","sequenceId":12},{"id":13,"end":62.84,"note":"","text":"1、家具職人としてのこだわり","start":59.07,"favorite":false,"stableId":"380d06e7-1c15-4a15-9a6a-6050fe413737","sequenceId":13},{"id":14,"end":69.1,"note":"","text":"2、家具に使用される木の種類","start":65.3,"favorite":false,"stableId":"3b288b51-5074-425b-adfa-a1523e2a99f8","sequenceId":14},{"id":15,"end":75.44,"note":"","text":"3、木の家具の手入れの仕方","start":71.65,"favorite":false,"stableId":"331f0729-3ce8-4819-a58a-923f9bf97109","sequenceId":15},{"id":16,"end":81.48,"note":"","text":"4、家具職人の大変さ","start":77.82,"favorite":false,"stableId":"b380b3a8-b842-4aff-b030-53512db370a0","sequenceId":16}],"jlptLevel":"N1","difficulty":"","transcript":"","description":"","jlptSession":"2025-07","sectionTitle":"概要理解","sectionNumber":3,"questionNumber":4,"listeningSectionTitle":"概要理解","questionEntryRequired":false,"listeningSectionNumber":3}', NULL, '2026-08-10T12:55:25.389+00:00', '2026-08-10T16:36:11.360+00:00'),
('b782b626-ffd0-5d0b-83ac-004c01eeb060', 'READING', '完璧に記憶でき、忘れない脳があったらいいと思う方もいるでしょう。しかし、記憶は不完全になるように、あたかも設定されているかのようです。それどころか、都合よく記憶', NULL, '{"text":"完璧に記憶でき、忘れない脳があったらいいと思う方もいるでしょう。しかし、記憶は不完全になるように、あたかも設定されているかのようです。それどころか、都合よく記憶同士を合成したり、書き換えたりすることも行われます。場合によっては、自分の昔の意図と現在の価値観との記憶が混在してしまう……というような事態も生じたりしてしまうわけです。\nかといって、完璧に記憶できる人が仮にいたとしたら、一体どうなるでしょうか。嫌な思い出を忘ることもできず、周囲に合わせるための都合のよい記憶の書き換えもできず、かえってつらい人生を送ることになるでしょう。\n記憶が徐々に消えていく、あるいは書き換わる仕組みが存在するのは、より良く生きていくためには自然で、当たり前のことだと言えます。\n例えば、体験した危険な出来事を学習し、同様の事象を回避するための安全装置として記憶の仕組みが発達してきたのだとすれば、一定期間その危険がやって来ないと、その条件の重みづけを変え、優先順位を下げる仕組みが必要になります。それよりも、高頻度かつ致命的な影響を与え得る危険の方を優先的に回避するべきで、なかなか起こらないことに記憶のリソースを割いていると、かえって重要なことに対応できず、危険な状態になってしまいます。また、過去の失敗だけでなく、成功体験にとらわれやすくなるため、前例のないことには新しい挑戦をしにくくなります。\nしたがって、人間の能力の一部に過ぎない記憶力をことさら重要視する現代の教育や受験制度は、せっかく最適化されてきたはずの人類の生存戦略をかえってゆがめてしまっている可能性があるのではないかと思います。テストでは高得点を取るために記憶力が高い人が有利になる仕組みですが、その結果をそのまま優秀であるかどうかのランキングとして使うのはいかがなものかと思います。\nというのも、テクノロジーの発達によって、不完全な人間の記憶力はどんどん補完されるようになってきており、実際にその仕組みは社会でも利用され始めているからです。文字をパソコンやスマートフォンで打つようであれば、漢字の書き順を忘れてしまう問題にはなりますし、そもそも人間の漢字記憶力は、パソコンやスマートフォンには絶対に勝てません。ならば、使用頻度がそれほど高くない漢字を覚えるより、素直に電子機器の恩恵にあらずつかたがよさそうです。\nこのような機器の性能はこれからさらに高まっていくわけですから、優秀な人を見分ける基準として記憶力という尺度を使うのは、多くの人が同じように感じていると思いますが、すでに時代にそぐわなくなってきているのかもしれません。","description":null}', '{}', '2026-04-03T06:20:06.429+00:00', '2026-04-03T06:20:06.429+00:00'),
('dd3dbe1b-d51f-5c3d-8877-aafe079dc46a', 'READING', '生活者に、「〇〇と言えば、自社の商品」という形で自社商品を第1に想起させるには、商品は広告の中に隠れかくれてはいけならない。しかしいつの間にか、商品を中心に置く', NULL, '{"text":"生活者に、「〇〇と言えば、自社の商品」という形で自社商品を第1に想起させるには、商品は広告の中に隠れかくれてはいけならない。しかしいつの間にか、商品を中心に置くということが広告をする上でなかなかできなくなっている。どの企業からも似たような商品しか出てこなくなり、商品のコモディティ化が進んできてしまったため、商品の差別化を、イメージだけでなんとか乗り切ろうとしている。テレビCMでもウェブ動画でも、商品の存在は最後の最後まで消し去られ、ちょっとおもしろい、ちょっと楽しい、ちょっと感動するような広告が繰り広げられ、最後のほんの一瞬に商品が紹介される広告。これらはたしかに、最後に登場する商品が仮に他社の商品でもなんとなく成立してしまう。広告はおもしろくてちょっと話題になるかもしれないが、話題の中心は広告であり、商品は忘れ去られている。なんの商品の広告だったか覚えられていない。\nこの様な、イメージによって差別化を図る最近のCMが批判されるのが、この数年、世界の広告でも取り上げられている「ソーシャルグッド」と呼ばれる種類の広告だろう。社会的な問題、たとえば国家対立や貧困、ジェンダー論といった世界の誰もが抱えている、もしくは理解できる問題を提起し、決してその問題を根本的に解決するわけではないが、生活者に考えるきっかけを与えたり、ちょっと気づかせたりする広告だ。「作品」として素晴らしいものばかりで、多くの気づきを与えてくれる。ただしこれらの広告により、どこまで生活者の態度変容を引き起こすことができたのかは疑問である。\n確かに素晴らしい気づきを与えてくれて、この様なメッセージを発信する商品は良いブランドだと感じる。ただし「良いブランド」止まりであり、これだけでは自分の生活を良くするのに必要な存在にはなれない。かつ、この様な良いメッセージを発信するばかりに、かえって近寄り難い存在になることもある。\n（中略）\n大切なのは広告で社会を変革をすることでも、良いイメージを与えることでもなく、商品を生活者にとって必要な存在にすることだ。商品を生活者にとって価値を理解してもらい、買うに値する理由を明確にすることだ。商品は、この世に必要だと思ってくれる人がいるから存在することができる。だからこそ明確な購買理由を提案していくのだ。\n\n（注1）想起する：思い起こす\n（注2）コモディティ化：一般化","description":null}', '{}', '2026-04-03T06:58:20.565+00:00', '2026-04-03T06:58:20.565+00:00'),
('4d3a0c16-d4e7-5fa0-a42b-51f488348e86', 'READING', '火を使って調理をするようになってから、人類はそれ以前よりも多くの種類の食べ物を食べられるようになり、しかもそれを効率よく消化して多くのエネルギーを得ることができ', NULL, '{"text":"火を使って調理をするようになってから、人類はそれ以前よりも多くの種類の食べ物を食べられるようになり、しかもそれを効率よく消化して多くのエネルギーを得ることができるようになった。そして、余ったエネルギーを使って脂肪を発達させて、優れた知的能力を獲得することになるのである。人類の歯、胃、腸、大腸などはチンパンジーなどに比べればはるかに小さくみえるが、それは火を使って調理した柔らかい食物に適応して進化した結果であると考えてよい。\n大きな消化器官を使って長時間の消化、吸収活動を行うことは多くのエネルギーを消費するから、消化器官が小さいものが生物学的に有利である。\n（中略）\n火で調理することには、人類の脳が発達させただけではなく、人類の社会性を発達させる効果もあった。火を使って調理することが人類の偉大な発明の一つとされているのは、食べ物を変質させただけではなく、社会を変容させたからである。火を使って生の食べ物を調理することを覚えたときから人類の社会が始まったと言ってよい。人は火の周りに集まり、一緒に食事をするようになったので、そこが人々の輪になった。調理とは、単に食べ物を煮炊きする方法ではなく、決まった時間に集団で食事をすることを中心にして社会を形成する方法でもあったのである。\n\n（注）チンパンジー：猿の一種","description":null}', '{}', '2026-04-02T23:31:51.186+00:00', '2026-04-02T23:31:51.186+00:00'),
('48dd89c9-e5c4-48d7-84d3-c3e3c55bd347', 'LISTENING', '問題2-02｜ポイント理解', NULL, '{"audioUrl":"/audios/listening/jlpt/n1/2025-07/2025-07-N1-P02-Q02.mp3","audioFile":"/audios/listening/jlpt/n1/2025-07/2025-07-N1-P02-Q02.mp3","dialogues":[{"id":1,"end":6.43,"text":"2番 テレビでアナウンサーが男の人にインタビューをしています。","start":0.22,"stableId":"95c61f4d-b9b2-4a6d-9828-2dc5aefbefb1","sequenceId":1},{"id":2,"end":13.48,"text":"男の人は自分のサッカーチームでプレイすることのどんな点がいいと言っていますか。","start":6.88,"stableId":"d97ae4fe-4a95-4d86-af52-697a58bad417","sequenceId":2},{"id":3,"end":39.92,"text":"今日はサッカーグラウンドに来ています。","start":36.86,"stableId":"02335e72-da6c-49e9-ae59-9ba0f397726f","sequenceId":3},{"id":4,"end":42.35,"text":"内田さんにお話を伺います。","start":40.05,"stableId":"3e61d72b-abf6-4bc9-a103-aa43748c1f9c","sequenceId":4},{"id":5,"end":43.53,"text":"内田です。","start":42.4,"stableId":"0e74ec0d-53e0-443d-aad8-c0f9fd189fc0","sequenceId":5},{"id":6,"end":48.21,"text":"このチームはメンバーが全員60歳以上なんです。","start":43.58,"stableId":"8384885e-7fd1-4d1e-8b02-9ecb1f8aa022","sequenceId":6},{"id":7,"end":50.99,"text":"60歳以上ということですが、","start":48.51,"stableId":"b4623fc0-3a35-4279-9de7-ff4d79a9993c","sequenceId":7},{"id":8,"end":53.57,"text":"皆さん大変お元気ですね。","start":51.04,"stableId":"a6e29c74-8c50-4dd9-b8ff-24685f6faa67","sequenceId":8},{"id":9,"end":59.33,"text":"いや、かつてのようにコートを全員で走り回ることに憧れていますが、","start":53.62,"stableId":"415e3c8d-2b7d-4dfe-9845-01a5e880b872","sequenceId":9},{"id":10,"end":65.32,"text":"私のチームには怪我や病気を経験し、十分に走れない人もいます。","start":59.38,"stableId":"6383288f-5d8c-44ab-b596-0d930fd9a2ee","sequenceId":10},{"id":11,"end":72.23,"text":"走れない人がボールを取られた時は全員でカバーを合い言葉にピンチをしのぐんです。","start":65.73,"stableId":"5d2ce732-7655-4f86-8453-3a75c42937d4","sequenceId":11},{"id":12,"end":77.8,"text":"この年齢ですから、みんなが満足いくプレイができるとは限りませんが、","start":72.69,"stableId":"4abd0c89-4211-4606-8136-f21a70037537","sequenceId":12},{"id":13,"end":79.68,"text":"互いに助け合います。","start":77.85,"stableId":"0eab8a24-1b54-4c2c-b13c-0d93bd602cd1","sequenceId":13},{"id":14,"end":82.77,"text":"このようなことが魅力だと感じます。","start":80.1,"stableId":"b6108984-805d-4089-8d67-55c19d3bc42d","sequenceId":14},{"id":15,"end":89.1,"text":"元気でいるためにも未経験の皆さんも是非参加してほしいですね。","start":83.23,"stableId":"7576b806-d75a-42fc-8416-5c931a950d10","sequenceId":15},{"id":16,"end":101.41,"text":"男の人は自分のサッカーチームでプレーすることのどんな点がいいと言っていますか。","start":94.52,"stableId":"5b9cc405-faf4-4f0f-93a8-eb8196316cb9","sequenceId":16}],"jlptLevel":"N1","jlptSession":"2025-07","sectionTitle":"ポイント理解","sectionNumber":2,"questionNumber":2,"listeningSectionTitle":"ポイント理解","questionEntryRequired":false,"listeningSectionNumber":2}', '{}', '2026-08-09T02:50:05.638+00:00', '2026-08-09T02:53:10.314+00:00');

INSERT OR IGNORE INTO "materials" ("id", "type", "title", "chapter_name", "content_payload", "metadata", "created_at", "updated_at") VALUES
('8ba676c9-021f-4ea2-a34c-2f02fef31be2', 'SPEAKING', '大学・専門学校入試の面接', '20', '{"audioUrl":"/audios/shadowing/面接編-新・シャドーイング-日本語を話そう/Unit2/20.mp3","audioFile":"/audios/shadowing/面接編-新・シャドーイング-日本語を話そう/Unit2/20.mp3","dialogues":[{"id":1,"end":4.42,"text":"失礼いたします。","start":3.02,"stableId":"2731a5bb-9c55-4714-a059-3eda2d9e54bd","sequenceId":1},{"id":2,"end":5.83,"text":"どうぞ。","start":4.96,"stableId":"d5e21f31-e585-4b61-b531-93a9738505ad","sequenceId":2},{"id":3,"end":8.66,"text":"受験番号と名前を教えてください。","start":6.02,"stableId":"35fe1c7c-3d4e-4d64-a2cf-91b74fe25f2f","sequenceId":3},{"id":4,"end":11.35,"text":"EC1253、","start":9.03,"stableId":"e390c7fc-a821-464a-8ee0-29301e4440c1","sequenceId":4},{"id":5,"end":12.91,"text":"グエン・バンブンです。","start":11.4,"stableId":"9cc28978-8bf5-4ea2-8af2-7255db07cc14","sequenceId":5},{"id":6,"end":15.82,"text":"はい。では、座ってください。","start":13.24,"stableId":"564dd872-0103-4fc7-b7e1-1e7967419390","sequenceId":6},{"id":7,"end":18.22,"text":"はい。失礼いたします。","start":16.2,"stableId":"a28d051b-8638-4f59-9409-a9df561179f5","sequenceId":7},{"id":8,"end":22.85,"text":"えー、面接の前の筆記試験はどうでしたか。","start":19.1,"stableId":"5cbcca4e-e961-4e97-8896-630deb8dae9f","sequenceId":8},{"id":9,"end":27.83,"text":"はい。えー、小論文のテーマが難しかったのですが、","start":23.09,"stableId":"a725e404-b8c2-477d-974a-f8179bf6d342","sequenceId":9},{"id":10,"end":31.53,"text":"今の時点で考えていることが書けたと思います。","start":28,"stableId":"517592fc-7bf8-4c05-be54-1f23f07fdd94","sequenceId":10},{"id":11,"end":33.36,"text":"あ、そうですか。","start":32.04,"stableId":"2c9d3cac-04a2-4fbf-8b41-75d622fff0f2","sequenceId":11},{"id":12,"end":37.42,"text":"グエンさんは日本語はどのぐらい勉強したんですか。","start":33.78,"stableId":"b15a4e58-ed30-4b72-b7ba-e0e947045b45","sequenceId":12},{"id":13,"end":43.13,"text":"ベトナムで半年、日本に来て日本語学校で１年勉強しました。","start":37.83,"stableId":"1e544891-b7f2-4851-8773-87ea6b6d72c5","sequenceId":13},{"id":14,"end":45.58,"text":"じゃ、1年半ですね。","start":43.53,"stableId":"24706eec-bda4-41ee-9e03-80877f0300c2","sequenceId":14},{"id":15,"end":48.31,"text":"日本語能力試験を受けましたか。","start":45.88,"stableId":"9da4d9f7-5176-475a-92c2-ece6b02b0b07","sequenceId":15},{"id":16,"end":53.08,"text":"はい。今年の7月にN2レベルに合格しました。","start":48.77,"stableId":"2f4264cf-8352-40f5-9f02-b7242110d8f3","sequenceId":16},{"id":17,"end":57.21,"text":"そして、12月にN1レベルを受験しました。","start":53.37,"stableId":"3888ecc3-43e8-4421-af44-6dfc4d7c7f7a","sequenceId":17},{"id":18,"end":59.66,"text":"結果はまだ来ていませんが、","start":57.68,"stableId":"bf57f4b7-318f-4f76-ae74-bf62590d50a2","sequenceId":18},{"id":19,"end":61.84,"text":"可能性はあると思っています。","start":59.71,"stableId":"ab33c05f-912f-454a-9500-ece06faab75a","sequenceId":19},{"id":20,"end":63.73,"text":"あ、そうですか。","start":62.3,"stableId":"6beea1dd-de09-438f-856d-d65fdae216cc","sequenceId":20},{"id":21,"end":67.66,"text":"グエンさんは本学についてはどこで知ったんですか。","start":64.08,"stableId":"9ca5fc40-b30b-4e0e-993d-da46c915e477","sequenceId":21},{"id":22,"end":75.6,"text":"はい。インターネットで「大阪」「大学」「経営学」といったキーワードで検索をしました。","start":68.17,"stableId":"8fbc303a-a047-467a-b543-ad521430d7d7","sequenceId":22},{"id":23,"end":79.45,"text":"その際にこちらの大学が目にとまりました。","start":75.89,"stableId":"8c46cda4-5058-4cf1-8b34-ae2c12ed42d8","sequenceId":23},{"id":24,"end":85.56,"text":"そして、SNSでこちらの大学で学んでいる留学生と知り合いになり、","start":79.74,"stableId":"decfe996-cb56-4863-88c8-f194d0a2b14e","sequenceId":24},{"id":25,"end":90.52,"text":"大学生活や卒業後の進路などについて教えてもらいました。","start":85.69,"stableId":"144930dd-a84f-4e47-9079-f9d538df79dc","sequenceId":25},{"id":26,"end":94.61,"text":"グエンさんは経営学部が第一志望ですね。","start":91.31,"stableId":"a508d266-f798-4da9-8d1c-f413a1634e4f","sequenceId":26},{"id":27,"end":97.84,"text":"では、志望動機をお聞かせください。","start":94.99,"stableId":"8b5ae25e-adb2-457f-8461-5e67876a5165","sequenceId":27},{"id":28,"end":105.06,"text":"はい。私は中小企業のマーケティングや市場戦略について学びたいと考えています。","start":98.3,"stableId":"fa4f7086-e27b-4964-8ba2-d2041e529473","sequenceId":28},{"id":29,"end":109.94,"text":"卒業後はできれば日本で就職して経験をつみ、","start":105.53,"stableId":"6a2d9419-d9ae-4ddb-b8b6-af09d2b1f2bf","sequenceId":29},{"id":30,"end":114.41,"text":"その後、帰国して自分自身も起業したいと考えています。","start":109.99,"stableId":"d6dfc46a-ff18-4515-8a06-f10c81a95abb","sequenceId":30},{"id":31,"end":119.32,"text":"えー、まだ具体的に業界などは絞り込めていませんが、","start":114.91,"stableId":"e729d0b6-7bee-4532-a371-248a0140fde4","sequenceId":31},{"id":32,"end":122.54,"text":"このように考え、経営学を志望しました。","start":119.37,"stableId":"ae66c6d4-dfff-42a1-9395-155cdd81b92b","sequenceId":32},{"id":33,"end":123.97,"text":"分かりました。","start":122.86,"stableId":"53c05379-9527-4264-8fe5-bb24d5df3d1b","sequenceId":33},{"id":34,"end":129.46,"text":"では、卒業後の希望はまずは日本での就職ということですね。","start":124.3,"stableId":"55ad52dd-3025-409e-9efa-70480ad1cc39","sequenceId":34},{"id":35,"end":134.48,"text":"はい。卒業後は大学院の進学も考えましたが、","start":129.94,"stableId":"d1cefee2-2b53-4b8a-8a58-f9dd0c2c8731","sequenceId":35},{"id":36,"end":138.82,"text":"経営学については知識と経験が必要だと考え、","start":134.66,"stableId":"94c6faa7-f5b5-44a6-a4b3-38bb11b81d11","sequenceId":36},{"id":37,"end":144.26,"text":"卒業後は日本での就職が何よりの学びの場だと考えています。","start":138.87,"stableId":"83c77acd-2be9-4e2f-a34b-9641b0e3b923","sequenceId":37},{"id":38,"end":147.58,"text":"ただ、まだ分からないことも多いので、","start":144.75,"stableId":"d783cefa-6b85-4d06-8cdf-aebcf57bdf71","sequenceId":38},{"id":39,"end":151.58,"text":"大学に入学して先生方にご指導をいただきながら、","start":147.63,"stableId":"7f571085-b2ff-4a53-9ad7-bc97a6e07495","sequenceId":39},{"id":40,"end":154.92,"text":"具体的なことを考えていきたいと思っています。","start":151.63,"stableId":"3ebdfdc9-8ee2-48b7-9b32-3a6e510f44a5","sequenceId":40},{"id":41,"end":156.62,"text":"そうですか。","start":155.57,"stableId":"b8debbb5-29f2-4182-8c3e-2d9a35ed63a8","sequenceId":41},{"id":42,"end":161.39,"text":"では、グエンさんの経済的な計画をお聞きしたいんですが、","start":157.08,"stableId":"ba0d4d74-803d-4654-863e-8fef72546200","sequenceId":42},{"id":43,"end":165.92,"text":"学費だとか生活費だとかは誰が負担する計画ですか。","start":161.44,"stableId":"0bfa1110-41ce-43b3-b0dc-474615c5ccd5","sequenceId":43},{"id":44,"end":172.74,"text":"はい。学費と当面の生活費は両親と親戚が負担してくれることになっています。","start":166.4,"stableId":"4b985d12-03f3-4d4f-93c6-780a81d5dbc5","sequenceId":44},{"id":45,"end":178.47,"text":"しかし２年目からの生活費はアルバイトをしてまかなおうと思っています。","start":173.15,"stableId":"5b0f0afb-1090-4cdb-a904-ceebd608b2a4","sequenceId":45},{"id":46,"end":183.53,"text":"また、夏休みや冬休みに一生懸命アルバイトして、","start":178.92,"stableId":"c2f38202-ccbe-43df-8326-3fc1a7b459e1","sequenceId":46},{"id":47,"end":187.16,"text":"勉強とアルバイトの両立をしたいと思っています。","start":183.6,"stableId":"b74f34ca-960a-47ad-9a90-1ebbdd6ced1d","sequenceId":47},{"id":48,"end":188.91,"text":"そうですか。","start":187.89,"stableId":"dfb71809-00da-45e5-92ec-05c08aa9d3f2","sequenceId":48},{"id":49,"end":190.79,"text":"なかなか大変ですね。","start":189.01,"stableId":"260bd45b-6129-462f-861d-c4b2478855b0","sequenceId":49},{"id":50,"end":195.8,"text":"では、最後にグエンさんから何か質問があればお聞きください。","start":191.22,"stableId":"afdfb73a-434e-4cd6-b124-d0343da336d1","sequenceId":50},{"id":51,"end":200.59,"text":"はい。あのー、少しアドバイスをいただきたいのですが…。","start":196.21,"stableId":"a209d88f-306f-41c8-9c39-e9a65460b1bc","sequenceId":51},{"id":52,"end":205.75,"text":"もし合格できたら、入学までに２ヶ月ぐらい時間がありますが、","start":200.96,"stableId":"488297ca-09d3-472c-988a-802c1f1930f4","sequenceId":52},{"id":53,"end":208.14,"text":"どんな勉強をしておけばいいでしょうか。","start":205.8,"stableId":"ffb0480d-2c14-4b95-8ce7-1a7773f9c899","sequenceId":53},{"id":54,"end":210.61,"text":"えー、そうですね。","start":208.76,"stableId":"7bd8ae90-b348-4dba-a5f2-29a9e9d206b0","sequenceId":54},{"id":55,"end":213.81,"text":"まずは新聞や雑誌を読むといいですね。","start":210.66,"stableId":"e6c544e0-e3a1-415c-9a85-8d7a0fdbd871","sequenceId":55},{"id":56,"end":220.73,"text":"新聞や雑誌の記事には経営についてもいろいろなヒントや教訓になることが書かれています。","start":213.97,"stableId":"a6a7f3ce-8e93-4783-a31c-4549daeee0bc","sequenceId":56},{"id":57,"end":223.07,"text":"難しいかもしれませんが、","start":221.09,"stableId":"3714c7f6-4ae2-467b-a0f8-b5f13d460673","sequenceId":57},{"id":58,"end":226.78,"text":"ぜひ読んで、その記事の裏側を考えてください。","start":223.12,"stableId":"eab5c6a1-b8d0-49e0-9776-368ea578dfcf","sequenceId":58},{"id":59,"end":231.96,"text":"なぜだろうと疑問に思うことが何よりもまず大切だと思います。","start":227.11,"stableId":"cce7ffd3-2dc9-4ce5-9793-d4d34f4b73ce","sequenceId":59},{"id":60,"end":234.47,"text":"はい。分かりました。","start":232.69,"stableId":"ffa7c39a-a250-45a9-8925-0e8e070a3cad","sequenceId":60},{"id":61,"end":235.93,"text":"ありがとうございます。","start":234.54,"stableId":"02f2193b-5a6a-4732-9f77-8bd6ae5066b4","sequenceId":61},{"id":62,"end":238.65,"text":"では、終わりにしましょう。","start":236.68,"stableId":"2a224459-5a4b-49e2-a585-0cf8512afad5","sequenceId":62},{"id":63,"end":241.45,"text":"はい。ありがとうございました。","start":239.1,"stableId":"3c7d96ae-33e6-4d85-9d9b-9c4b5bcca5e4","sequenceId":63},{"id":64,"end":243.33,"text":"失礼いたします。","start":242.04,"stableId":"beb991e2-e4ff-4b68-b2d0-6d4c6d4fa068","sequenceId":64}]}', NULL, '2026-04-19T23:49:08.227+00:00', '2026-08-10T16:47:29.232+00:00'),
('b262491d-c752-4008-b68c-72bc338a6192', 'SPEAKING', 'Section3', 'Section3', '{"tags":[],"source":"","audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit5/Unit05Section03.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit5/Unit05Section03.mp3","dialogues":[{"id":1228,"end":6.5,"text":"1、明日の今ごろは、北海道にいるんです。","start":2.01,"sequenceId":1},{"id":1229,"end":8.78,"text":"えー、いいなー。","start":6.55,"sequenceId":2},{"id":1230,"end":10.21,"text":"何しに行くの？","start":8.83,"sequenceId":3},{"id":1231,"end":12.54,"text":"うん、ただの出張だよ。","start":10.26,"sequenceId":4},{"id":1232,"end":17.08,"text":"2、ねー、歯にのりついてない？","start":13.41,"sequenceId":5},{"id":1233,"end":18.37,"text":"うん、大丈夫。","start":17.13,"sequenceId":6},{"id":1234,"end":19.42,"text":"私は？","start":18.42,"sequenceId":7},{"id":1235,"end":22.41,"text":"あ、なんか、右のほうについてるよ。","start":19.55,"sequenceId":8},{"id":1236,"end":27.09,"text":"3、オレのみそ汁を作ってくれ！","start":23.61,"sequenceId":9},{"id":1237,"end":29.72,"text":"え、それってプロポーズ？","start":27.14,"sequenceId":10},{"id":1238,"end":31.09,"text":"あー。","start":30.02,"sequenceId":11},{"id":1239,"end":39.15,"text":"4、昨日、行った店、食べ放題、飲み放題で2980円だったよ。","start":32.49,"sequenceId":12},{"id":1240,"end":41.33,"text":"それって、けっこうやすいね。","start":39.2,"sequenceId":13},{"id":1241,"end":43.28,"text":"その店どこにあるんですか？","start":41.38,"sequenceId":14},{"id":1242,"end":44.82,"text":"駅の向こう側。","start":43.33,"sequenceId":15},{"id":1243,"end":46.78,"text":"ちょっと説明難しいなー。","start":44.87,"sequenceId":16},{"id":1244,"end":49.39,"text":"じゃ、今日、帰りに教えてよ。","start":46.83,"sequenceId":17},{"id":1245,"end":56.12,"text":"5、田中さんの結婚パーティーっていつでしたっけ？","start":51.79,"sequenceId":18},{"id":1246,"end":59.82,"text":"えー、確か10日の3時からです。","start":56.17,"sequenceId":19},{"id":1247,"end":62.14,"text":"え、10日でしたっけ？","start":59.9,"sequenceId":20},{"id":1248,"end":67.49,"text":"6、今日、寝過ごしてびっくりしたよ。","start":63.17,"sequenceId":21},{"id":1249,"end":69.19,"text":"起きたらもう8時なんだもん。","start":67.54,"sequenceId":22},{"id":1250,"end":71.92,"text":"へー。でもよく間に合ったね。","start":69.24,"sequenceId":23},{"id":1251,"end":74.31,"text":"うん。でも焦ったよ。","start":71.97,"sequenceId":24},{"id":1252,"end":79.48,"text":"7、すごい肩だね。","start":76.42,"sequenceId":25},{"id":1253,"end":81.75,"text":"こってるね。どう？","start":79.53,"sequenceId":26},{"id":1254,"end":84.65,"text":"あー、すごく気持ちいい。","start":81.82,"sequenceId":27},{"id":1255,"end":87.81,"text":"あ、もういいよ。どうもありがとう。","start":85,"sequenceId":28},{"id":1256,"end":88.84,"text":"いえいえ。","start":87.86,"sequenceId":29},{"id":1257,"end":91.87,"text":"あー、本当に気持ちよかった。","start":88.89,"sequenceId":30},{"id":1258,"end":93.05,"text":"軽くなった。","start":91.92,"sequenceId":31},{"id":1259,"end":97.07,"text":"8、ねー、シャツ見て。","start":93.75,"sequenceId":32},{"id":1260,"end":100.42,"text":"これとこれ、今日どっちの方がいいと思う？","start":97.15,"sequenceId":33},{"id":1261,"end":103.69,"text":"どちらかって言えば、こっちかな。","start":100.48,"sequenceId":34},{"id":1262,"end":104.95,"text":"そう？","start":103.85,"sequenceId":35},{"id":1263,"end":107.13,"text":"でも、こっちの方がよくない？","start":105.08,"sequenceId":36},{"id":1264,"end":108.15,"text":"なーんだ！","start":107.18,"sequenceId":37},{"id":1265,"end":110.81,"text":"人に聞いといて、もう決まってるんだ。","start":108.2,"sequenceId":38},{"id":1266,"end":115.61,"text":"9、あ、もう帰んなくちゃ。","start":112.29,"sequenceId":39},{"id":1267,"end":117.22,"text":"え、早いね。","start":115.66,"sequenceId":40},{"id":1268,"end":120.1,"text":"うん、今晩、気になる番組があるから。","start":117.27,"sequenceId":41},{"id":1269,"end":125.22,"text":"10、うわー、日焼けしたね。","start":121.58,"sequenceId":42},{"id":1270,"end":126.25,"text":"どこ行ったの？","start":125.27,"sequenceId":43},{"id":1271,"end":128.33,"text":"うん、ちょっとハワイにね。","start":126.3,"sequenceId":44},{"id":1272,"end":130.08,"text":"ちょっとハワイ？","start":128.38,"sequenceId":45}],"difficulty":"","transcript":"","description":""}', NULL, '2026-04-04T22:36:51.234+00:00', '2026-08-10T16:47:29.234+00:00'),
('1c261fe6-384a-43ec-8c15-c3cb8dc6a187', 'SPEAKING', 'Section08', 'Section08', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit4/Unit04Section08.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit4/Unit04Section08.mp3","dialogues":[{"id":1124,"end":5.45,"text":"1、明日、時間通りに来てね。","start":1.87,"sequenceId":1},{"id":1125,"end":6.49,"text":"大丈夫。","start":5.5,"sequenceId":2},{"id":1126,"end":8.2,"text":"10分前に来ますから。","start":6.54,"sequenceId":3},{"id":1127,"end":12.83,"text":"2、どこで乗り換えるんでしたっけ？","start":9.52,"sequenceId":4},{"id":1128,"end":14.89,"text":"新宿が便利ですよ。","start":12.99,"sequenceId":5},{"id":1129,"end":19.17,"text":"3、終電に間に合う？","start":16.12,"sequenceId":6},{"id":1130,"end":20.59,"text":"ぎりぎりかな。","start":19.22,"sequenceId":7},{"id":1131,"end":21.82,"text":"急がなくちゃ。","start":20.64,"sequenceId":8},{"id":1132,"end":26.31,"text":"4、売店はどこですか？","start":23.33,"sequenceId":9},{"id":1133,"end":30.28,"text":"ホーム中央の階段をあがったら、右手にありますよ。","start":26.36,"sequenceId":10},{"id":1134,"end":34.94,"text":"5、この電車は渋谷に行きますか？","start":31.26,"sequenceId":11},{"id":1135,"end":38.38,"text":"ええ。でも、銀座線の方が早いですよ。","start":34.99,"sequenceId":12},{"id":1136,"end":44.34,"text":"6、15引く9はいくつ？","start":40.47,"sequenceId":13},{"id":1137,"end":46.12,"text":"6ですよ。","start":44.39,"sequenceId":14},{"id":1138,"end":51.2,"text":"7、6足す15はいくつ？","start":47.39,"sequenceId":15},{"id":1139,"end":54.1,"text":"6足す15は21でしょう。","start":51.25,"sequenceId":16},{"id":1140,"end":59.8,"text":"8、何か意見があれば、遠慮なく言ってください。","start":55.37,"sequenceId":17},{"id":1141,"end":61.29,"text":"特にありません。","start":59.85,"sequenceId":18},{"id":1142,"end":66.01,"text":"9、わざわざありがとうございました。","start":62.43,"sequenceId":19},{"id":1143,"end":67.37,"text":"とんでもないです。","start":66.06,"sequenceId":20},{"id":1144,"end":72.3,"text":"10、ご心配をおかけしました。","start":68.84,"sequenceId":21},{"id":1145,"end":74.76,"text":"いいえ。大変でしたね。","start":72.35,"sequenceId":22}]}', '{}', '2026-04-03T04:38:43.744+00:00', '2026-04-08T00:10:53.468+00:00'),
('1f304e9d-91c6-4e9c-9bf1-3a47b67a5985', 'SPEAKING', 'Is This Your Shirt', 'Lesson11', '{"audioUrl":"/audios/shadowing/新概念英语第一册/Unit1/011012-Is-This-Your-Shirt.mp3","audioFile":"/audios/shadowing/新概念英语第一册/Unit1/011012-Is-This-Your-Shirt.mp3","dialogues":[{"id":1,"end":5.39,"text":"Lesson 11 Is this your shirt?","start":0.79,"sequenceId":1},{"id":2,"end":11.61,"text":"Listen to the tape then answer this question.","start":6.6,"sequenceId":2},{"id":3,"end":15.41,"text":"Whose shirt is white?","start":13.15,"sequenceId":3},{"id":4,"end":19.25,"text":"Whose shirt is that?","start":17.1,"sequenceId":4},{"id":5,"end":22.54,"text":"Is this your shirt,Dave?","start":19.98,"sequenceId":5},{"id":6,"end":24.51,"text":"No ,sir.","start":23.12,"sequenceId":6},{"id":7,"end":26.71,"text":"It''s not my shirt.","start":24.56,"sequenceId":7},{"id":8,"end":30.06,"text":"This is my shirt.","start":27.83,"sequenceId":8},{"id":9,"end":32.37,"text":"My shirt''s blue.","start":30.37,"sequenceId":9},{"id":10,"end":35.76,"text":"Is this shirt Tim''s?","start":33.23,"sequenceId":10},{"id":11,"end":38.74,"text":"Perhaps it is,sir.","start":36.46,"sequenceId":11},{"id":12,"end":41.71,"text":"Tim''s shirt''s white.","start":39.45,"sequenceId":12},{"id":13,"end":43.11,"text":"Tim!","start":42.16,"sequenceId":13},{"id":14,"end":44.84,"text":"Yes,sir?","start":43.67,"sequenceId":14},{"id":15,"end":47.3,"text":"Is this your shirt?","start":45.26,"sequenceId":15},{"id":16,"end":48.54,"text":"Yes,sir.","start":47.35,"sequenceId":16},{"id":17,"end":50.26,"text":"Here you are.","start":48.76,"sequenceId":17},{"id":18,"end":51.41,"text":"Catch!","start":50.38,"sequenceId":18},{"id":19,"end":53.12,"text":"Thank you,sir.","start":51.46,"sequenceId":19}]}', NULL, '2026-04-09T05:17:48.558+00:00', '2026-08-10T16:47:29.251+00:00'),
('84ccd2a2-0649-5f12-b01f-de85d08aa0ae', 'VOCAB_GRAMMAR', '2025年7月N1', NULL, '{"description":null}', '{}', '2026-03-31T05:59:59.945+00:00', '2026-03-31T05:59:59.945+00:00'),
('732dff00-86c2-404f-a7bb-1bab2562d28f', 'SPEAKING', '大学・専門学校入試の面接', '14', '{"audioUrl":"/audios/shadowing/面接編-新・シャドーイング-日本語を話そう/Unit2/14.mp3","audioFile":"/audios/shadowing/面接編-新・シャドーイング-日本語を話そう/Unit2/14.mp3","dialogues":[{"id":1,"end":6.23,"text":"8、大学で一番学びたいことは何ですか。","start":0.77,"sequenceId":1},{"id":2,"end":10.86,"text":"はい。一番という意味では専門の勉強です。","start":7.01,"sequenceId":2},{"id":3,"end":15.45,"text":"しかし、それ以外にも就職活動のことを考えて、","start":11.24,"sequenceId":3},{"id":4,"end":18.57,"text":"できるだけ人と多く接する機会を作り、","start":15.5,"sequenceId":4},{"id":5,"end":21.47,"text":"様々な経験を積みたいと思っています。","start":18.62,"sequenceId":5},{"id":6,"end":27.31,"text":"そのためにアルバイトをしたり大学行事に参加したいと思っています。","start":22.01,"sequenceId":6},{"id":7,"end":34.28,"text":"また、一生付き合えるような日本人の友人や先生に出会えればと思っています。","start":27.67,"sequenceId":7},{"id":8,"end":41.57,"text":"9、本校についてはどうやって知ったんですか。","start":36.45,"sequenceId":8},{"id":9,"end":49.83,"text":"はい。インターネットで「日本」「専門学校」「アニメーション」といったキーワードで検索をしました。","start":42.25,"sequenceId":9},{"id":10,"end":53.98,"text":"その際にこちらの専門学校が目にとまりました。","start":50.11,"sequenceId":10},{"id":11,"end":60.22,"text":"そしてSNSでこちらの大学で学んでいる留学生と知り合いになり、","start":54.27,"sequenceId":11},{"id":12,"end":65.2,"text":"学校生活や卒業後の進路などについて教えてもらいました。","start":60.27,"sequenceId":12},{"id":13,"end":72.95,"text":"10、どうしてこの専門学校を志望したんですか。","start":67.47,"sequenceId":13},{"id":14,"end":82.3,"text":"はい。観光学が学べること、学ぶための環境、そして生活するための環境が整っていること、","start":73.5,"sequenceId":14},{"id":15,"end":86.11,"text":"この3つの点から専門学校を検討しました。","start":82.46,"sequenceId":15},{"id":16,"end":91.48,"text":"大きな学校では教員一人に対する学生数が多く、","start":86.84,"sequenceId":16},{"id":17,"end":96.18,"text":"また人と人との距離が離れているのではないかと思いました。","start":91.56,"sequenceId":17},{"id":18,"end":103.98,"text":"そこで私は中規模あるいは小規模の専門学校が自分にとっては良いと考えました。","start":96.62,"sequenceId":18},{"id":19,"end":112.83,"text":"私自身、韓国の地方都市の出身なので日本でも地方都市の方が居心地がいいだろうと思い、","start":104.57,"sequenceId":19},{"id":20,"end":116.88,"text":"こうした理由からこちらの専門学校を志望しました。","start":112.88,"sequenceId":20}]}', NULL, '2026-04-13T05:41:36.447+00:00', '2026-08-10T16:47:29.252+00:00'),
('9f5d6b49-0c80-5e03-ab82-35447659a3b9', 'READING', 'ワサビは生育環境を選ぶ植物であるため、系統維持が非常に難しく、栽培者がいなくなれば、維持されてきたワサビも一緒に消失してしまう。山に行けば野生が自生しているから', NULL, '{"text":"ワサビは生育環境を選ぶ植物であるため、系統維持が非常に難しく、栽培者がいなくなれば、維持されてきたワサビも一緒に消失してしまう。山に行けば野生が自生しているから大丈夫、という考えは間違いである。野生個体は栽培者と根茎も太らず、辛くない。長い時間をかけてできた品種は、一度失われてしまったら、容易には復元できないのだ。だからこそ、植物資源として大切に守る必要があるといえる。\n\n（注）系統維持：ここでは、種の特徴が受け継がれていくこと","description":null}', '{}', '2026-04-02T04:24:21.099+00:00', '2026-04-02T04:24:21.099+00:00'),
('f2102cb3-0b43-4791-9370-e03c74ec5a73', 'SPEAKING', 'Section1', 'Section1', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit5/Unit05Section01.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit5/Unit05Section01.mp3","dialogues":[{"id":1146,"end":7.1,"text":"1、今年の目標は？","start":3.74,"sequenceId":1},{"id":1147,"end":8.64,"text":"そうですね。","start":7.32,"sequenceId":2},{"id":1148,"end":12.36,"text":"英会話を始めようと思っているので、それを続けることです。","start":8.72,"sequenceId":3},{"id":1149,"end":15.12,"text":"「継続は力なり」ですね。","start":12.41,"sequenceId":4},{"id":1150,"end":20.15,"text":"2、明日の約束忘れないでね。","start":16.47,"sequenceId":5},{"id":1151,"end":21.66,"text":"大丈夫だよ。","start":20.28,"sequenceId":6},{"id":1152,"end":22.42,"text":"たぶん…。","start":21.71,"sequenceId":7},{"id":1153,"end":24.44,"text":"え、たぶん？","start":22.47,"sequenceId":8},{"id":1154,"end":28.44,"text":"3、すみません。","start":26.14,"sequenceId":9},{"id":1155,"end":31.24,"text":"出席率を調べていただきたいんですが。","start":28.49,"sequenceId":10},{"id":1156,"end":32.7,"text":"あ、はい。","start":31.29,"sequenceId":11},{"id":1157,"end":35.23,"text":"次の休み時間までに調べておきます。","start":32.85,"sequenceId":12},{"id":1158,"end":37.3,"text":"じゃ、よろしくお願いします。","start":35.28,"sequenceId":13},{"id":1159,"end":42.53,"text":"4、小林さん、何見てるの？","start":38.93,"sequenceId":14},{"id":1160,"end":44.7,"text":"この間の旅行の写真。","start":42.77,"sequenceId":15},{"id":1161,"end":46.95,"text":"え、どこいったの？","start":44.75,"sequenceId":16},{"id":1162,"end":50.92,"text":"5、すみません。","start":48.59,"sequenceId":17},{"id":1163,"end":53.64,"text":"コピーをさせていただいてもよろしいですか？","start":50.97,"sequenceId":18},{"id":1164,"end":55.2,"text":"あ、はい。","start":53.79,"sequenceId":19},{"id":1165,"end":56.15,"text":"どうぞ。","start":55.25,"sequenceId":20},{"id":1166,"end":57.63,"text":"ありがとうございます。","start":56.2,"sequenceId":21},{"id":1167,"end":61.76,"text":"6、ハックション！","start":59.24,"sequenceId":22},{"id":1168,"end":63.22,"text":"ハックション！","start":62.07,"sequenceId":23},{"id":1169,"end":64.11,"text":"あれ？","start":63.27,"sequenceId":24},{"id":1170,"end":65.17,"text":"花粉症？","start":64.16,"sequenceId":25},{"id":1171,"end":66.6,"text":"ハックション！","start":65.22,"sequenceId":26},{"id":1172,"end":72.08,"text":"7、卒業したらどうするんですか？","start":68.65,"sequenceId":27},{"id":1173,"end":75.46,"text":"外資系の会社に就職することが決まったんです。","start":72.34,"sequenceId":28},{"id":1174,"end":77.8,"text":"あ、それはよかったですね。","start":75.51,"sequenceId":29},{"id":1175,"end":83.2,"text":"8、そう言えば、昨日田中さんにあったよ。","start":80.13,"sequenceId":30},{"id":1176,"end":85.35,"text":"へー、元気だった？","start":83.28,"sequenceId":31},{"id":1177,"end":87.57,"text":"うん、ぜんぜんわからないよ。","start":85.4,"sequenceId":32},{"id":1178,"end":94.06,"text":"9、きりがよかったら、こっちでコーヒー飲まない？","start":89.53,"sequenceId":33},{"id":1179,"end":96.26,"text":"うん。もうちょっと待ってて。","start":94.39,"sequenceId":34},{"id":1180,"end":97.66,"text":"じゃ、入れとくね。","start":96.31,"sequenceId":35},{"id":1181,"end":103.35,"text":"10、このコンピューター、だれか使ってるの？","start":99.06,"sequenceId":36},{"id":1182,"end":105.74,"text":"あ、それ落としといて。","start":103.64,"sequenceId":37},{"id":1183,"end":108.66,"text":"あれ、このワード、どうしよう。","start":105.87,"sequenceId":38},{"id":1184,"end":110.94,"text":"あ、上書きしといて。","start":108.88,"sequenceId":39}]}', '{}', '2026-04-04T04:50:11.330+00:00', '2026-04-08T00:10:44.016+00:00'),
('1f5b4eeb-4d32-5bc7-b5e6-d381a0701335', 'VOCAB_GRAMMAR', '2025年12月N1', NULL, '{"description":null}', '{}', '2026-04-03T07:33:19.692+00:00', '2026-04-03T07:33:19.692+00:00'),
('06c2264e-7de1-4978-ae6a-b8e52e42db2a', 'SPEAKING', 'Section3', 'Section3', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit1/Unit01Section03.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit1/Unit01Section03.mp3","dialogues":[{"id":69,"end":5.06,"text":"1、何時ですか？","start":2.08,"sequenceId":1},{"id":70,"end":6.2,"text":"9時です。","start":5.14,"sequenceId":2},{"id":71,"end":9.48,"text":"2、今、何時ですか？","start":6.47,"sequenceId":3},{"id":72,"end":10.45,"text":"4時。","start":9.53,"sequenceId":4},{"id":73,"end":13.98,"text":"3、何時にねましたか？","start":10.95,"sequenceId":5},{"id":74,"end":15.75,"text":"11時半ぐらいです。","start":14.03,"sequenceId":6},{"id":75,"end":19.54,"text":"4、テストは何時からですか？","start":16.31,"sequenceId":7},{"id":76,"end":21.02,"text":"10時からですよ。","start":19.59,"sequenceId":8},{"id":77,"end":24.77,"text":"5、今日は何日ですか？","start":21.6,"sequenceId":9},{"id":78,"end":26.44,"text":"4月1日です。","start":24.82,"sequenceId":10},{"id":79,"end":29.81,"text":"6、今日は何曜日？","start":26.67,"sequenceId":11},{"id":80,"end":31.31,"text":"水曜日だよ。","start":29.99,"sequenceId":12},{"id":81,"end":35.24,"text":"7、誕生日はいつですか？","start":31.93,"sequenceId":13},{"id":82,"end":36.9,"text":"8月20日です。","start":35.29,"sequenceId":14},{"id":83,"end":41.64,"text":"8、銀行は何時から何時までですか？","start":37.33,"sequenceId":15},{"id":84,"end":43.61,"text":"9時から3時までです。","start":41.8,"sequenceId":16},{"id":85,"end":47.01,"text":"9、今年は何年？","start":44.07,"sequenceId":17},{"id":86,"end":50.01,"text":"2006年。平成18年だよ。","start":47.06,"sequenceId":18},{"id":87,"end":54.83,"text":"10、日本に来て、どのぐらいですか？","start":50.72,"sequenceId":19},{"id":88,"end":56.77,"text":"1年3ヶ月です。","start":54.95,"sequenceId":20}]}', '{}', '2026-04-01T15:03:14.000+00:00', '2026-04-08T00:32:50.671+00:00'),
('40829ea9-5b8e-4443-81be-785c1222f738', 'SPEAKING', '電話アポイントメント', '05', '{"audioUrl":"/audios/shadowing/面接編-新・シャドーイング-日本語を話そう/Unit1/05.mp3","audioFile":"/audios/shadowing/面接編-新・シャドーイング-日本語を話そう/Unit1/05.mp3","dialogues":[{"id":1368,"end":4.14,"text":"12、お名前は？","start":0.86,"sequenceId":1},{"id":1369,"end":6.65,"text":"トッツ　タン　コン　トゥエン　と申します。","start":4.31,"sequenceId":2},{"id":1370,"end":8.42,"text":"あ、すみません。","start":6.97,"sequenceId":3},{"id":1371,"end":10.93,"text":"もう一度、ゆっくりお願いします。","start":8.47,"sequenceId":4},{"id":1372,"end":12.61,"text":"すみません。","start":11.51,"sequenceId":5},{"id":1373,"end":14.18,"text":"コンと呼んでください。","start":12.66,"sequenceId":6},{"id":1374,"end":20.58,"text":"13、じゃ、いつがいいかな。","start":16.38,"sequenceId":7},{"id":1375,"end":23.22,"text":"来週木曜日の2時頃はどう？","start":20.77,"sequenceId":8},{"id":1376,"end":29.24,"text":"来週の木曜日、13日の2時ですか、","start":23.73,"sequenceId":9},{"id":1377,"end":30.86,"text":"すみません…。","start":29.67,"sequenceId":10},{"id":1378,"end":33.59,"text":"あ、都合が悪いんですか。","start":31.36,"sequenceId":11},{"id":1379,"end":35.2,"text":"すみません。","start":34.13,"sequenceId":12},{"id":1380,"end":38.67,"text":"その日は大学の試験があって面接は…。","start":35.25,"sequenceId":13},{"id":1381,"end":45.62,"text":"14、はい、人事部の山田です。","start":40.78,"sequenceId":14},{"id":1382,"end":51.22,"text":"あ、もしもし、今日面接の予定のアルフレッドですが、","start":46.07,"sequenceId":15},{"id":1383,"end":54.74,"text":"すみませんが少し遅れてしまいそうなんです。","start":51.39,"sequenceId":16},{"id":1384,"end":57,"text":"え、どうしたんですか？","start":55.28,"sequenceId":17},{"id":1385,"end":61,"text":"電車が人身事故で止まってしまったんです。","start":57.52,"sequenceId":18},{"id":1386,"end":66.1,"text":"15、そうですか。","start":62.65,"sequenceId":19},{"id":1387,"end":69.27,"text":"電車、どのくらい遅れそうですか。","start":66.62,"sequenceId":20},{"id":1388,"end":72.55,"text":"あと15分ほどで動きそうです。","start":69.66,"sequenceId":21},{"id":1389,"end":74.79,"text":"じゃ、待ってますから。","start":73.09,"sequenceId":22},{"id":1390,"end":76.58,"text":"気を付けて来てくださいね。","start":74.84,"sequenceId":23},{"id":1391,"end":78.48,"text":"ありがとうございます。","start":76.98,"sequenceId":24},{"id":1392,"end":81.07,"text":"ご迷惑をおかけしてすみません。","start":78.6,"sequenceId":25}]}', '{}', '2026-04-07T05:20:23.077+00:00', '2026-04-09T04:55:55.518+00:00'),
('a1ddf2b0-c287-5abb-95b7-8f8b5660a2c1', 'READING', '知性は個人の属性ではなく、集団的にしか発動しない。', NULL, '{"text":"知性は個人の属性ではなく、集団的にしか発動しない。\nだから、ある個人が知性的であるかどうかは、その人の個人が私的に所有する知識量や知能指数や演算能力によっては量れない。そうではなくて、その人がいる集団と集団全体の知的パフォーマンスによって、合成的に語られる。ある人が賢いか、賢くないかの判断を誤った場合、事後的にその人は「知性的」な人物だったと判定される。\n\n（注1）属性：性質\n（注2）考量：判断する","description":null}', '{}', '2026-04-02T04:25:46.469+00:00', '2026-04-02T04:25:46.469+00:00'),
('66f1466e-ed8f-5b10-8a9e-5d0e075d66d2', 'READING', 'いまはコミュニケーション能力が過剰に求められる時代である。職場でも学校でも、あるいはもっとプライベートな空間でもいい。あらゆる人間関係において、自分の価値を認め', NULL, '{"text":"いまはコミュニケーション能力が過剰に求められる時代である。職場でも学校でも、あるいはもっとプライベートな空間でもいい。あらゆる人間関係において、自分の価値を認めてもらうためには高度なコミュニケーション能力が必要とされる。書店に行けばコミュニケーション能力を高めるための自己啓発本があり余るほどでているし、わざわざそのための学校に通う人もいるほどだ。\n確かに、いまの産業のあり方をみると、コミュニケーションが富を生み出す経済活動の中心にきていることがわかる。製造業は人件費の安い海外に工場をどんどん移転させ、国内に残っているのは、マネジメントや企画、研究開発、マーケティングといった本社機能的な仕事ばかり。そこでは、組織をまとめあげる、アイディアをだす、交渉する、プレゼンをする、ディスカッションをするといった、高いコミュニケーション能力が必要とされる活動がどうしても物を言う。社会のあり方が、工場中心からコミュニケーション中心へと大きく転換しているのである。\nしかし、コミュニケーション能力が、人々の価値を決める独占的な尺度になることは、はたして健全なのだろうか。事実、コミュニケーションべたで自己アピールにそれほど長けていなくても、能力のある人はいっぱいいる。私も大学でゼミを指導していると、ゼミの議論では目立っていてもリポートの出来はそれほどでもない学生や、逆にゼミではおとなしくても素晴らしいリポートを書いてくる学生に頻繁にであう。コミュニケーションの巧みさと本人の能力は必ずしも一致しない。\nもちろんコミュニケーション能力も人間の能力の一つではある。だから、それが評価基準の一つになることは当然あっていい。とはいえ、コミュニケーション能力をめぐる過当な競争は、人間関係にひずみをももたらすだろう。\n引きこもりは、社会のなかで要求されるコミュニケーション能力があまりに高いため、一度他者とのコミュニケーションにつまずくと、なかなか新たなコミュニケーションに踏み出せなくなってしまうことから生まれる。引きこもりまでいかなくても、周りとのコミュニケーションのなかで自分がまともに相手にされなければ、誰だって心を閉ざしてしまい、内にこもりがちになるだろう。コミュニケーション能力をめぐる競争が激しい社会は、それにつまずいてしまった人にとても冷淡だ。\nまた、いじめは子供たちのコミュニケーション能力の欠如から起きているのではなく、逆に、みんなが空気を読みすぎることで生じるストレスのはけ口を特定の人間に向けることで起きている。こうしたストレスや重圧は、子供に限った問題ではない。空気を壊してはならないという圧力は、人々とコミュニケーション能力をさらに要求するだろう。しかしそれが進めば、社会のなかで同調圧力が強まり、社会そのものが萎縮してしまうのだろうか。","description":""}', '{}', '2026-03-31T05:10:31.416+00:00', '2026-03-31T05:10:31.416+00:00'),
('dfec4764-554f-497f-ba65-3690f8ed0e06', 'SPEAKING', 'Lesson9', 'Lesson9', '{"audioUrl":"/audios/shadowing/新概念英语第一册/Unit1/009010-How-Are-You-Today.mp3","audioFile":"/audios/shadowing/新概念英语第一册/Unit1/009010-How-Are-You-Today.mp3","dialogues":[{"id":929,"end":4.93,"text":"Lesson 9 How are you today?","start":0.51,"sequenceId":1},{"id":930,"end":10.77,"text":"Listen to the tape then answer this question.","start":5.75,"sequenceId":2},{"id":931,"end":13.51,"text":"How is Emma?","start":11.48,"sequenceId":3},{"id":932,"end":16.87,"text":"Hello Helen.","start":15.14,"sequenceId":4},{"id":933,"end":18.71,"text":"Hi Steven.","start":17.1,"sequenceId":5},{"id":934,"end":21.32,"text":"How are you today?","start":19.01,"sequenceId":6},{"id":935,"end":24.24,"text":"I''m very well thank you.","start":21.59,"sequenceId":7},{"id":936,"end":25.41,"text":"And you?","start":24.29,"sequenceId":8},{"id":937,"end":27.93,"text":"I''m fine thanks.","start":25.69,"sequenceId":9},{"id":938,"end":30.55,"text":"How is Tony?","start":28.75,"sequenceId":10},{"id":939,"end":33.2,"text":"He''s fine thanks.","start":30.77,"sequenceId":11},{"id":940,"end":34.73,"text":"How''s Emma?","start":33.32,"sequenceId":12},{"id":941,"end":37.93,"text":"She''s very well too Helen.","start":34.86,"sequenceId":13},{"id":942,"end":40.63,"text":"Goodbye Helen.","start":39.16,"sequenceId":14},{"id":943,"end":42.34,"text":"Nice to see you.","start":40.68,"sequenceId":15},{"id":944,"end":46.08,"text":"Nice to see you too Steven.","start":42.68,"sequenceId":16},{"id":945,"end":47.32,"text":"Goodbye.","start":46.13,"sequenceId":17}]}', '{}', '2026-04-01T15:03:14.000+00:00', '2026-04-08T00:32:59.019+00:00'),
('ae4c8ab5-1003-5376-bad7-bebd8cc6241b', 'READING', 'ネコの目の前に指先を出すと、必ずクンクンにおいをかぎますね。じつは、これはネコ同士のあいさつに由来するしぐさです。', NULL, '{"text":"ネコの目の前に指先を出すと、必ずクンクンにおいをかぎますね。じつは、これはネコ同士のあいさつに由来するしぐさです。\n私たち人間はおじぎをしたり握手をしてあいさつをしますが、ネコたちにとっては、鼻と鼻を近づけてお互いにおいをかぐのがあいさつです。ネコの目はわりに退化していて、特別なにおいを出す器官があります。それぞれはネコによって異なるため、鼻を近づけると相手がどこの誰か、そして敵か味方かなどの情報を知ることができるのです。\nこのようにネコがにおいで相手を確認するのは、目があまり[1]。ネコは肉食のハンターですから抜群の視力をもっていそうですが、人間にたとえると0.3程度の近眼だとされています。つまりかなり近づかないと相手の顔を確認できないということ。\nだから、人間の指先を見ても、ネコは鼻を近づけられたと勘違いして同じ反応を[2]。指先だとわかっていても、習慣的に「とりあえず、あいさつだけはしておこう」と考えるのでしょう。おきまりのクンクンが始まります。\nこの習性を[3]、初対面のネコとも仲よくできます。いきなりなでたり抱っこしようとすれば嫌がります。これは、あなたが何者かわからないからです。\n[4]まずは指先をネコの鼻に近づけてみましょう。ひととおり指のにおいをかいだ後でネコが逃げなければ、それはあなたに好意をもったという証拠ですから、そのとき触れても嫌がらないはずです。","description":""}', '{}', '2026-04-02T00:39:11.016+00:00', '2026-04-02T00:39:11.016+00:00'),
('161e83c3-9b2b-5c71-a2e5-ba41f8ae848b', 'READING', '自動車メーカーが、製造・販売した自動車に不具合が見つかったとして、無償で修理をするリコールを行うことはよくあります。', NULL, '{"text":"自動車メーカーが、製造・販売した自動車に不具合が見つかったとして、無償で修理をするリコールを行うことはよくあります。\n\nリスクゼロ思考からすると、そもそも不具合のある車を世に出すべきではないということになります。事前に不具合が出ることがわかっているなら、そんな車はつくらないはずです。不具合が絶対に出ない車しかつくってはいけないというのなら、メーカーは何もつくれなくなります。\n\nそれよりも、不具合が出たらリコールして、次につくる車からは同じ不具合が出ないように改善していくのが理論的な発想です。","description":""}', '{}', '2026-04-02T01:52:19.633+00:00', '2026-04-02T01:52:19.633+00:00'),
('9534d7f7-aa39-5fbf-b174-87581353c310', 'READING', '以下は、母語の音声の習得について日本語を例として書かれた文章である。', NULL, '{"text":"以下は、母語の音声の習得について日本語を例として書かれた文章である。\n「赤ちゃんのときはどんな音でも区別できるのに、成長するとできなくなる」といわれるのは、決して聞き分け能力の劣化ではなく、日本語の音体系に対応して「区別しないものを見いだし、同じと見なすことを学ぶ」という変化なのだ。こと音の知覚に関しては「習得は喪失だ」といわれるゆえんである。諸々の外国語で、日本語では区別しない音の聞き分けに苦労した経験があるならば、それは自分が日本語習得にいかに完全に成功したかを示しているのだ、と思ってよい。\n\n（注1）こと：ここでは、特に\n（注2）ゆえん：理由\n（注3）諸々の：多くの","description":null}', '{}', '2026-04-02T04:22:37.567+00:00', '2026-04-02T04:22:37.567+00:00'),
('74b3f5e4-301d-5693-b517-558edb7dc63a', 'READING', '以下は、キャリア教育の専門家が書いた文章である。', NULL, '{"text":"以下は、キャリア教育の専門家が書いた文章である。\n自分にはどんな仕事が向いていて、どんな仕事であれば、やりがいや誇りをもって働けるのか。一すでに仕事をしている人だって、こんな問いに答えるのは、そう容易なことではない。実感をもって答えられるようになるには、何年もの就業経験が必要なはずである。\nましてや、いまだ働いたこともない子どもや若者の場合、キャリア教育で「魔法」でもかけられないかぎり、こんな問いに答えることができなくて当然である。その意味で、「やりたいこと」や「就きたい職業」を選び、決めるということは、一種の「賭け」である。\nもちろん、「賭け」がいけないわけではない。仕事の世界は、いったんは思いきって飛び込んでみないかぎり、それを理解することはできない。その意味で、最後は最後の段階での勝負は必要なのだ。しかし、そのまえにやっておくべきことはある。（中略）その職業や仕事の世界について、産業構造のなかでの位置や業界の動き、職場や労働環境について、現実的認識をもっていなくてはいけない。\nさらに言えば、自分が、なぜその職業・仕事を選ぶのかについて、みずからの「根っこ」にあるものについても見つめ、深めさせたい。キャリア研究の世界では、この「根っこ」のことを「キャリアアンカー」といったりもする。「根っこ」の部分には、その仕事に就くことを通じて、どんなふうに社会に役立ちたいか、どんな社会を実現したいか、自分のこんな特性を生かしたいといった、思いや価値観が存在するはずである。","description":null}', '{}', '2026-04-03T05:31:27.071+00:00', '2026-04-03T05:31:27.071+00:00'),
('22a15efd-87b2-503e-a9fb-249f1ba59e08', 'READING', '2018年に、米国のデューク大学のエレナ・ケイガスたちは、カリブ海の水深1～35mのサンゴ礁に棲息するクリーナーシュリンプ（アシキロスネス・ペデルソニ）がブダイ', NULL, '{"text":"2018年に、米国のデューク大学のエレナ・ケイガスたちは、カリブ海の水深1～35mのサンゴ礁に棲息するクリーナーシュリンプ（アシキロスネス・ペデルソニ）がブダイやエイ、ハタなどの魚の体や口を掃除するときの行動を調べた。すると魚とクリーナーシュリンプが、それぞれ相手に安心してもよいと思える信号を出していることが明らかになった。\nまず、ハタなどの魚が、目に長い触角を振るクリーナーシュリンプが棲む場所を訪ねて来て、魚が体表を晒すると、（中略）\n体表の明暗の変化をクリーナーシュリンプが認識すると、自らの長い触角を前後左右に大きく振る。クリーナーシュリンプの一種アシキロスネス・ペデルソニの視力は、相手の魚の色や輪郭ははっきり認識できるが、魚の体表の明暗の変化は十分に認識できることが明らかになっている。いっぽうで、ハタなどの魚の視力は、クリーナーシュリンプの触角の動きが、30～40cmほど前方にいる全長2cmほどの小さなクリーナーシュリンプの細い触角の動きを明確に識別できる。クリーナーシュリンプの触角に白く長いものが多いことは、触角の動きを視覚的に強調して明確に魚に伝えるためのものと思われる。\nその触角の動きを見て、ハタなどの魚は、クリーナーシュリンプが皮膚や口の中をきれいにしたいという意思を察し、すなわちそれを妨害しないしないと位置を定めるようになると考えられる。互いに信号を確認し合意すれば、クリーナーシュリンプは、ハタなどの魚に食べられずに掃除を行うことが可能になる。\n\n（注1）棲息する：住む\n（注2）クリーナーシュリンプ：えびの一種\n（注3）触角：頭の先にある感覚器官","description":null}', '{}', '2026-04-03T05:48:31.352+00:00', '2026-04-03T05:48:31.352+00:00'),
('b1c905b5-31d6-582d-b8f2-0af2a5dd4615', 'READING', '自分で自分の書いた日記を読み返し、そこに描かれている「私」の姿にとまどいや自己嫌悪を感じた経験はないだろうか。', NULL, '{"text":"自分で自分の書いた日記を読み返し、そこに描かれている「私」の姿にとまどいや自己嫌悪を感じた経験はないだろうか。\n\n描かれている「私」はたしかに自分であるはずなのだけれども、まるで別人のようにも感じられる。いわば赤の他人のような――見異なる人物写真はながらも自分自身でもある、という二重感覚があらわれるときといえる。羞恥や嫌悪の引き金になるのである。\n\nいや、こうした言い方はあまり正確ではないかもしれない。たとえば写真で過去の自分の姿を見た時、われわれが感じるのは羞恥や嫌悪よりも、むしろ「たしかに自分もいたのだ」というおかしさや懐かしさである。両者の本質的な客体性を保持しているのは、日記は言葉で書かれているために、本来外に出るものではない「内面」を露呈してしまっている。そのためわれわれは勝手な「内面」づくりをいとわしんでいた、まさにその行為にいたたまれなさを感じるのだ。\n\n日記に登場する「私」は実にさまざまだ。友人と喧嘩したときの記述は自分が都合よく正当化してしまっているかもしれないし、失恋したときの記述はこの世の悲劇を一身に背負ったヒーロー、あるいはヒロインになってしまっていることもある。その時の要請に応じてフィクショナルに仮構された「内面」が、今、読み返している「私」と同一であると強いられるがゆえ、われわれはいかんがたい羞恥や嫌悪を感じてしまうのである。\n\n（注1）赤の他人：全くの他人\n（注2）羞恥：恥ずかしさ\n（注3）露呈する：ここでは、あからさまになる\n（注4）いとしむ：嫌む\n（注5）フィクショナルに仮構された：ここでは、事実とは異なる脳内の\n（注6）いかんがたい：ここでは、簡単には説明できない","description":null}', '{}', '2026-04-03T06:10:59.339+00:00', '2026-04-03T06:10:59.339+00:00'),
('a3c0f6f9-6ade-57b5-a87b-bf61a13eac5d', 'READING', 'A', NULL, '{"text":"A\n日本の家事を頑張りすぎて疲れてしまっている人が多いという。情報番組や雑誌で「整った快適な住まい」や「健康のための手作りの食事」などが頻繁に取り上げられるので、知らないうちに自分の基準が必要以上に高くなり、多くの時間や労力を費やしてしまっているのではないか。\nこういう人たちは手を抜くのは悪いことだと思うかもしれない。しかし「毎日しなければならない」「どのレベルまでやらなければならない」といったことは、本来自分で決めるものだ。正解はないはずなのに、いつのまにか世の中の高い基準に縛られてはいないだろうか。他人の基準ではなく自分が何を大切にしたいかを考え、そうでないことには積極的に手を抜いていくことが、ゆとりのある、自分らしい生き方につながるだろう。\n\nB\n生活の中で、何を大切にし、何を手放していくかは人それぞれに違います。周りの人にとっては無駄に思えても、自分にとってそれが大切なものであれば、それは手放さずに残せばいい。\nただ、あまりにも抱えているものが多いという人もいます。これは絶対にやらなければならない――生真面目な人ほどそう思い込んでしまうものです。\n（中略）\nあまり自分を追い詰めないで、時々は手を抜いてみましょう。手を抜いたことで何らかの支障が出たなら、そのときに従来通りに戻せばいい。手を抜いても何も変わらないのであれば、それはやらなくてもいいものと考えるわけです。\n手を抜くという行為は悪いことだと思われがちですが、そうではありません。すべてのことを完璧にするのは無理なことです。大切なことは、手を抜いていいものといいえないものを仕分けすることだと思います。\n（注）そぎ落とす：ここでは、削る","description":null}', '{}', '2026-04-03T06:52:40.902+00:00', '2026-04-03T06:52:40.902+00:00'),
('23976af0-bb55-49b7-8fc1-c674a63af074', 'SPEAKING', 'Section6', 'Section6', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit4/Unit04Section06.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit4/Unit04Section06.mp3","dialogues":[{"id":1075,"end":6.67,"text":"1、何、これ、食べ終わったら片付けなさい！","start":2.06,"sequenceId":1},{"id":1076,"end":10.47,"text":"あー、それまだ食べかけなんだから、おいといてよ。","start":6.72,"sequenceId":2},{"id":1077,"end":16.53,"text":"2、引越しの当日は、田中君が手伝ってくれるんだって。","start":11.36,"sequenceId":3},{"id":1078,"end":19.55,"text":"あ、本当。よかったね。","start":16.61,"sequenceId":4},{"id":1079,"end":24.99,"text":"3、この前の大会、拓也、４位だって。","start":20.24,"sequenceId":5},{"id":1080,"end":27.25,"text":"あ、本当〜。","start":25.35,"sequenceId":6},{"id":1081,"end":30.25,"text":"あいつにすれば、まあ、よくやったんじゃん？","start":27.51,"sequenceId":7},{"id":1082,"end":35.14,"text":"4、どこかかゆいところはありませんか？","start":31.03,"sequenceId":8},{"id":1083,"end":37.21,"text":"あ、大丈夫です。","start":35.45,"sequenceId":9},{"id":1084,"end":41.04,"text":"5、この漬け物、いけるね。","start":37.57,"sequenceId":10},{"id":1085,"end":43.23,"text":"お、そうだろ〜。","start":41.19,"sequenceId":11},{"id":1086,"end":45.67,"text":"それ、おばあちゃんが送ってくれたんだよ。","start":43.28,"sequenceId":12},{"id":1087,"end":51.49,"text":"6、友だちだからって、許せないことだってあるよ。","start":46.63,"sequenceId":13},{"id":1088,"end":54.27,"text":"まあ、そりゃそうだろうけどさー。","start":51.64,"sequenceId":14},{"id":1089,"end":58.66,"text":"7、な〜に、その投げやりな態度！","start":54.6,"sequenceId":15},{"id":1090,"end":60.21,"text":"別に〜。","start":58.71,"sequenceId":16},{"id":1091,"end":65.08,"text":"8、カラオケ行って、どんな曲歌うの？","start":60.6,"sequenceId":17},{"id":1092,"end":67.92,"text":"J-ポップが多いかな、最近の。","start":65.19,"sequenceId":18},{"id":1093,"end":72.85,"text":"9、車の免許とか持ってないの？","start":69.04,"sequenceId":19},{"id":1094,"end":75.72,"text":"あ、僕まだ16なんです。","start":73.09,"sequenceId":20},{"id":1095,"end":82.21,"text":"10、あ〜あ、どうしてあんなことしちゃったんだろう。","start":76.48,"sequenceId":21},{"id":1096,"end":83.97,"text":"まあ、そう言うなって。","start":82.42,"sequenceId":22},{"id":1097,"end":87.27,"text":"だれにしろ、そういう瞬間はあるんだから。","start":83.97,"sequenceId":23}]}', '{}', '2026-04-03T03:58:02.885+00:00', '2026-04-08T00:10:53.468+00:00'),
('72fd6ddf-1d8e-487f-9c52-6bfd6a328bfd', 'SPEAKING', 'Section1', 'Section1', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit3/Unit03Section01.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit3/Unit03Section01.mp3","dialogues":[{"id":492,"end":8.34,"text":"1、ジョンさんの部屋は家賃いくらですか？","start":3.59,"sequenceId":1},{"id":493,"end":10.07,"text":"月5万円です。","start":8.52,"sequenceId":2},{"id":494,"end":13.68,"text":"2、ホテル予約してある？","start":10.76,"sequenceId":3},{"id":495,"end":15.83,"text":"うん。昨日していたよ。","start":13.93,"sequenceId":4},{"id":496,"end":18.87,"text":"3、あ、見て！","start":16.66,"sequenceId":5},{"id":497,"end":21.25,"text":" 昨日の台風で木が倒れてる！","start":18.92,"sequenceId":6},{"id":498,"end":22.45,"text":"本当だ。","start":21.3,"sequenceId":7},{"id":499,"end":24.18,"text":"すごい風だったんだね。","start":22.5,"sequenceId":8},{"id":500,"end":28.12,"text":"4、リンさん、宿題は？","start":24.74,"sequenceId":9},{"id":501,"end":32.87,"text":"あ、先生、今朝が来ているので来週出してもいいですか？","start":28.28,"sequenceId":10},{"id":502,"end":35.37,"text":"5、あれ？","start":33.49,"sequenceId":11},{"id":503,"end":38.9,"text":"今日、お弁当、自分で作ったの？","start":35.46,"sequenceId":12},{"id":504,"end":41.8,"text":"いや、彼女に作ってもらいました。","start":39.13,"sequenceId":13},{"id":505,"end":47.35,"text":"6、山田さん、そのくつきつくないですか？","start":42.88,"sequenceId":14},{"id":506,"end":49.48,"text":"ううん、ぴったり。","start":47.42,"sequenceId":15},{"id":507,"end":52.85,"text":"7、あれ？","start":50.79,"sequenceId":16},{"id":508,"end":54.58,"text":"ドアが開いていますね。","start":52.92,"sequenceId":17},{"id":509,"end":55.98,"text":"本当だ。","start":54.97,"sequenceId":18},{"id":510,"end":57.74,"text":"だれが開けたんでしょうね。","start":56.03,"sequenceId":19},{"id":511,"end":61.59,"text":"8、ね、聞いた？","start":58.4,"sequenceId":20},{"id":512,"end":65.45,"text":"田中さん、宝くじで100万円当たったそうだよ。","start":61.67,"sequenceId":21},{"id":513,"end":67.96,"text":"へー、おごってもらおう。","start":65.51,"sequenceId":22},{"id":514,"end":71.74,"text":"9、ごめん、待った？","start":69.01,"sequenceId":23},{"id":515,"end":74.52,"text":"ううん、僕も今来たところ。","start":71.88,"sequenceId":24},{"id":516,"end":77.93,"text":"10、おいしそう！","start":75.56,"sequenceId":25},{"id":517,"end":79.08,"text":"本当だ。","start":77.98,"sequenceId":26},{"id":518,"end":81.63,"text":"あ、試食があるから食べてみよう。","start":79.13,"sequenceId":27}]}', '{}', '2026-04-01T15:03:14.000+00:00', '2026-04-08T00:11:01.768+00:00'),
('79c4dff6-d257-4812-9421-47587a1c939d', 'SPEAKING', 'Section9', 'Section9', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit2/Unit02Section09.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit2/Unit02Section09.mp3","dialogues":[{"id":463,"end":5.54,"text":"1、大人はいいよね。","start":2.16,"sequenceId":1},{"id":464,"end":7.54,"text":"え？ どうして？","start":5.75,"sequenceId":2},{"id":465,"end":9.91,"text":"嫌いなものを食べなくていいから。","start":7.59,"sequenceId":3},{"id":466,"end":12.29,"text":"あ〜、そうだね。","start":10.04,"sequenceId":4},{"id":467,"end":13.57,"text":"自由だよね。","start":12.34,"sequenceId":5},{"id":468,"end":20.5,"text":"2、先生、「安い」と「野菜」は似ていますね。","start":14.39,"sequenceId":6},{"id":469,"end":22.48,"text":"ええ、そうですね。","start":20.66,"sequenceId":7},{"id":470,"end":25.15,"text":"何かいい覚え方がありますか？","start":22.58,"sequenceId":8},{"id":471,"end":27.21,"text":"そうですね〜。","start":25.41,"sequenceId":9},{"id":472,"end":34.12,"text":"「やすい」はスーパーのス、「やさい」はサラダのサ、どうですか？","start":27.41,"sequenceId":10},{"id":473,"end":38.88,"text":"3、あ、しまった！","start":36,"sequenceId":11},{"id":474,"end":40.88,"text":"ん？ どうしたの？","start":38.99,"sequenceId":12},{"id":475,"end":44.13,"text":"昨日した宿題、うちに忘れてきちゃった。","start":40.93,"sequenceId":13},{"id":476,"end":52.73,"text":"4、来週の土曜日、バーベキューするけど、山田さんも来ない？","start":46.34,"sequenceId":14},{"id":477,"end":55.73,"text":"あ〜、土曜日か…。","start":52.92,"sequenceId":15},{"id":478,"end":57.85,"text":"土曜日はちょっと…。","start":55.78,"sequenceId":16},{"id":479,"end":61.12,"text":"あ、そう。残念…。","start":57.9,"sequenceId":17},{"id":480,"end":63.56,"text":"うーん、だれが来るの？","start":61.17,"sequenceId":18},{"id":481,"end":66.59,"text":"リンダさんとかホルヘさんとか…。","start":63.68,"sequenceId":19},{"id":482,"end":69.23,"text":"へー、いいな〜。","start":66.64,"sequenceId":20},{"id":483,"end":70.98,"text":"行きたいんだけどね…。","start":69.28,"sequenceId":21},{"id":484,"end":76.05,"text":"5、これ作ったんだ。","start":73.59,"sequenceId":22},{"id":485,"end":77.48,"text":"ちょっと食べてみて！","start":76.1,"sequenceId":23},{"id":486,"end":79.75,"text":"え、パンを自分で？","start":77.62,"sequenceId":24},{"id":487,"end":81.12,"text":"すごいね。","start":79.8,"sequenceId":25},{"id":488,"end":82.66,"text":"じゃ、一口。","start":81.17,"sequenceId":26},{"id":489,"end":83.93,"text":"どう？","start":82.98,"sequenceId":27},{"id":490,"end":88.38,"text":"うーん。おいしいかな、まあまあ。","start":84.32,"sequenceId":28},{"id":491,"end":90.37,"text":"あ、そう…。","start":88.64,"sequenceId":29}]}', '{}', '2026-04-01T15:03:14.000+00:00', '2026-04-08T00:32:35.637+00:00'),
('8434e546-c97d-4ce4-817d-84f5f8fc4fd6', 'SPEAKING', 'Section6', 'Section6', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit2/Unit02Section06.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit2/Unit02Section06.mp3","dialogues":[{"id":392,"end":6.51,"text":"1、ねー、ねー、あのさ〜。","start":2.1,"sequenceId":1},{"id":393,"end":8.29,"text":"あ、ちょっとごめんね。","start":6.51,"sequenceId":2},{"id":394,"end":9.6,"text":"後でもいい？","start":8.34,"sequenceId":3},{"id":395,"end":15.8,"text":"2、ねーねー、今日、キムさんが初めて宿題してきたんだよ。","start":10.86,"sequenceId":4},{"id":396,"end":18.59,"text":"へー！ 明日は雪だね。","start":15.85,"sequenceId":5},{"id":397,"end":24.43,"text":"3、来週の土曜、映画に行くけど、一緒に行きませんか？","start":19.76,"sequenceId":6},{"id":398,"end":27,"text":"あ、土曜はちょっと…。","start":24.48,"sequenceId":7},{"id":399,"end":30.76,"text":"4、すみません。","start":28.01,"sequenceId":8},{"id":400,"end":32.1,"text":"ちょっとよろしいですか？","start":30.81,"sequenceId":9},{"id":401,"end":34.83,"text":"あ、リカルドさん、何ですか。","start":32.15,"sequenceId":10},{"id":402,"end":41.61,"text":"5、ふふ。昨日ねー、愛子さんとデートしたんだ。","start":36.36,"sequenceId":11},{"id":403,"end":43.19,"text":"えー、すごい！","start":41.66,"sequenceId":12},{"id":404,"end":44.84,"text":"で、楽しかった？","start":43.24,"sequenceId":13},{"id":405,"end":46.46,"text":"どこ行って何したの？","start":44.89,"sequenceId":14},{"id":406,"end":52.04,"text":"6、今日は午後から台風が来るそうですね。","start":48.13,"sequenceId":15},{"id":407,"end":54.46,"text":"うん、早く帰った方がいいね。","start":52.09,"sequenceId":16},{"id":408,"end":59.16,"text":"7、ねー、まだバス来ないの？","start":55.74,"sequenceId":17},{"id":409,"end":61.12,"text":"うん、遅いね。","start":59.21,"sequenceId":18},{"id":410,"end":65.32,"text":"8、あれ？","start":62.95,"sequenceId":19},{"id":411,"end":67.08,"text":"この時計、合ってる？","start":65.37,"sequenceId":20},{"id":412,"end":69.59,"text":"うん、私のと同じだけど。","start":67.13,"sequenceId":21},{"id":413,"end":74.77,"text":"9、レポート、これでいいですか？","start":71.55,"sequenceId":22},{"id":414,"end":76.95,"text":"はい、いいようですね。","start":74.82,"sequenceId":23},{"id":415,"end":78.24,"text":"がんばりましたね。","start":77,"sequenceId":24},{"id":416,"end":82.93,"text":"10、明日の飲み会、来られる？","start":79.75,"sequenceId":25},{"id":417,"end":85.37,"text":"うん、ちょっと遅れて行くよ。","start":82.98,"sequenceId":26}]}', '{}', '2026-04-01T15:03:14.000+00:00', '2026-04-08T00:32:35.637+00:00'),
('d2ca1291-2cb3-4453-8850-d90cdc1d385f', 'SPEAKING', 'Section3', 'Section3', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit3/Unit03Section03.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit3/Unit03Section03.mp3","dialogues":[{"id":733,"end":7.05,"text":"1、ね、そのクッキー、一口ちょうだい。","start":2.46,"sequenceId":1},{"id":734,"end":9.55,"text":"あー、もう全部食べちゃった。","start":7.1,"sequenceId":2},{"id":735,"end":10.69,"text":"ごめんごめん。","start":9.6,"sequenceId":3},{"id":736,"end":14.48,"text":"2、あ、雨が降ってる。","start":11.3,"sequenceId":4},{"id":737,"end":18.01,"text":"あ、じゃ、このかさ貸してあげる。","start":15.17,"sequenceId":5},{"id":738,"end":19.2,"text":"2本あるから。","start":18.06,"sequenceId":6},{"id":739,"end":22.68,"text":"3、お茶、どうぞ。","start":20.07,"sequenceId":7},{"id":740,"end":24.89,"text":"熱いのでお気をつけください。","start":22.85,"sequenceId":8},{"id":741,"end":26.74,"text":"あ、すみません。","start":24.96,"sequenceId":9},{"id":742,"end":30.71,"text":"4、もしもし、山田さん？","start":27.51,"sequenceId":10},{"id":743,"end":33.15,"text":"今、話して大丈夫？","start":30.76,"sequenceId":11},{"id":744,"end":34.91,"text":"あ、ごめん。","start":33.4,"sequenceId":12},{"id":745,"end":36.87,"text":"今シャワー浴びていたところなんだ。","start":34.96,"sequenceId":13},{"id":746,"end":38.32,"text":"後で電話していい？","start":36.92,"sequenceId":14},{"id":747,"end":42.36,"text":"5、ねー、聞いた？","start":39.72,"sequenceId":15},{"id":748,"end":44.89,"text":"山田さん、結婚するんだって。","start":42.44,"sequenceId":16},{"id":749,"end":47.38,"text":"うん、おめでたらしいよ。","start":45.11,"sequenceId":17},{"id":750,"end":53.28,"text":"6、あれ？ ビデオデッキに変なビデオが入っていますね。","start":48.21,"sequenceId":18},{"id":751,"end":56.31,"text":"本当だ。だれが入れたんでしょうね。","start":53.43,"sequenceId":19},{"id":752,"end":60.59,"text":"7、ねー、もっときれいに書いてください。","start":56.92,"sequenceId":20},{"id":753,"end":62.62,"text":"これなんて書いてあるんですか？","start":60.64,"sequenceId":21},{"id":754,"end":65.16,"text":"あー、なんでしょう…。","start":62.71,"sequenceId":22},{"id":755,"end":66.79,"text":"私も読めません…。","start":65.21,"sequenceId":23},{"id":756,"end":72.41,"text":"8、ねー、飛行機の予約してある？","start":67.91,"sequenceId":24},{"id":757,"end":74.45,"text":"あ、ごめんなさい。","start":72.72,"sequenceId":25},{"id":758,"end":75.73,"text":"今、しておきます。","start":74.5,"sequenceId":26},{"id":759,"end":81.05,"text":"9、約束したのにどうして来てくれなかったの？","start":76.83,"sequenceId":27},{"id":760,"end":83.59,"text":"ごめん。本当にごめん。","start":81.27,"sequenceId":28},{"id":761,"end":86.03,"text":"どうしても会議ぬけられなかったんだ。","start":83.64,"sequenceId":29},{"id":762,"end":90.6,"text":"10、今度、ご飯でもいかがですか？","start":86.9,"sequenceId":30},{"id":763,"end":92.5,"text":"あ、ぜひ。","start":90.86,"sequenceId":31}]}', '{}', '2026-04-01T15:03:14.000+00:00', '2026-04-08T00:11:01.768+00:00');

INSERT OR IGNORE INTO "materials" ("id", "type", "title", "chapter_name", "content_payload", "metadata", "created_at", "updated_at") VALUES
('db7c54cf-2fb6-43c0-b42f-ec0faf0377bc', 'SPEAKING', 'Section4', 'Section4', '{"audioUrl":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit1/Unit01Section04.mp3","audioFile":"/audios/shadowing/初中级-シャドーイング-日本語を話そう/Unit1/Unit01Section04.mp3","dialogues":[{"id":89,"end":4.97,"text":"1、はじめまして。","start":2.06,"sequenceId":1},{"id":90,"end":6.2,"text":"渡辺です。","start":5.02,"sequenceId":2},{"id":91,"end":7.22,"text":"田中です。","start":6.25,"sequenceId":3},{"id":92,"end":8.35,"text":"どうぞよろしく。","start":7.27,"sequenceId":4},{"id":93,"end":11.35,"text":"2、鈴木さんですか？","start":8.85,"sequenceId":5},{"id":94,"end":13.03,"text":"はい、そうです。","start":11.46,"sequenceId":6},{"id":95,"end":16.39,"text":"3、佐藤さんですか？","start":13.75,"sequenceId":7},{"id":96,"end":18.39,"text":"いいえ、加藤です。","start":16.47,"sequenceId":8},{"id":97,"end":22.36,"text":"4、あれは日本語で何ですか？","start":18.98,"sequenceId":9},{"id":98,"end":23.3,"text":"あれ？","start":22.41,"sequenceId":10},{"id":99,"end":25.4,"text":"あ、あれは交番ですよ。","start":23.35,"sequenceId":11},{"id":100,"end":28.8,"text":"5、それはなんですか？","start":26.19,"sequenceId":12},{"id":101,"end":30.15,"text":"デジカメです。","start":28.88,"sequenceId":13},{"id":102,"end":34.98,"text":"6、山田さんの部屋は何階ですか？","start":31.07,"sequenceId":14},{"id":103,"end":36.24,"text":"3階です。","start":35.06,"sequenceId":15},{"id":104,"end":39.59,"text":"7、お名前は？","start":37.09,"sequenceId":16},{"id":105,"end":40.76,"text":"ペドロです。","start":39.69,"sequenceId":17},{"id":106,"end":41.87,"text":"お国は？","start":40.81,"sequenceId":18},{"id":107,"end":43.03,"text":"スペインです。","start":41.92,"sequenceId":19},{"id":108,"end":47.69,"text":"8、ノート、3冊ください。","start":44.05,"sequenceId":20},{"id":109,"end":49.85,"text":"はい、3冊ですね。","start":47.75,"sequenceId":21},{"id":110,"end":53.89,"text":"9、駅までどのぐらいですか？","start":50.53,"sequenceId":22},{"id":111,"end":55.75,"text":"1キロぐらいです。","start":54.21,"sequenceId":23},{"id":112,"end":60.07,"text":"10、新宿駅はどこですか？","start":56.4,"sequenceId":24},{"id":113,"end":61.51,"text":"あそこですよ。","start":60.28,"sequenceId":25}]}', '{}', '2026-04-01T15:03:14.000+00:00', '2026-04-08T00:32:50.671+00:00'),
('f7c5bcf0-c1cb-4562-93ca-e6ceeb414827', 'SPEAKING', 'アルバイト面接', '08', '{"audioUrl":"/audios/shadowing/面接編-新・シャドーイング-日本語を話そう/Unit1/08.mp3","audioFile":"/audios/shadowing/面接編-新・シャドーイング-日本語を話そう/Unit1/08.mp3","dialogues":[{"id":1,"end":7.31,"text":"13、ここの仕事、朝早いし、きついし大変だよ。","start":0.69,"sequenceId":1},{"id":2,"end":8.81,"text":"それでも大丈夫？","start":7.36,"sequenceId":2},{"id":3,"end":10.65,"text":"はい、大丈夫です。","start":9.05,"sequenceId":3},{"id":4,"end":12.85,"text":"体力には自信があります。","start":10.7,"sequenceId":4},{"id":5,"end":13.98,"text":"そう。","start":13.23,"sequenceId":5},{"id":6,"end":18,"text":"でも、途中で辞められるとこっちも困るんだけど。","start":14.05,"sequenceId":6},{"id":7,"end":19.81,"text":"そんなことありません。","start":18.27,"sequenceId":7},{"id":8,"end":22.05,"text":"一生懸命頑張ります。","start":19.99,"sequenceId":8},{"id":9,"end":32.36,"text":"14、人手が足りない時、時々残業とか休日出勤をお願いすることもありますが、","start":24.17,"sequenceId":9},{"id":10,"end":33.59,"text":"大丈夫ですか？","start":32.41,"sequenceId":10},{"id":11,"end":37.19,"text":"はい、できる限り引き受けたいと思います。","start":33.98,"sequenceId":11},{"id":12,"end":40.64,"text":"そう、そうしてくれるとこっちも助かるよ。","start":37.52,"sequenceId":12},{"id":13,"end":43.85,"text":"はい。そうできるように頑張ります。","start":41.25,"sequenceId":13},{"id":14,"end":51.2,"text":"15、そうか、希望はホールスタッフなんですね。","start":46.06,"sequenceId":14},{"id":15,"end":56.27,"text":"でも、今の日本語力なら、まずはキッチンスタッフで入って、","start":51.61,"sequenceId":15},{"id":16,"end":59.36,"text":"うちのメニューとかをまず覚えていてもらいましょうか。","start":56.32,"sequenceId":16},{"id":17,"end":61.67,"text":"はい。わかりました。","start":59.71,"sequenceId":17},{"id":18,"end":64.41,"text":"調理とかの経験はありますか？","start":62.19,"sequenceId":18},{"id":19,"end":69.26,"text":"アルバイトでの調理経験はありませんが、自炊はしています。","start":64.71,"sequenceId":19},{"id":20,"end":78.45,"text":"16、勤務時間は9時スタートなら13時あがりか、4時半あがり。","start":71.37,"sequenceId":20},{"id":21,"end":84.21,"text":"ま、バイトに慣れて忙しい時はラストまで、通してお願いすることもあるかな。","start":78.64,"sequenceId":21},{"id":22,"end":87.01,"text":"ラストは何時までですか？","start":84.51,"sequenceId":22},{"id":23,"end":91.96,"text":"お客さんは9時までで、そのあと掃除して10時には終わります。","start":87.31,"sequenceId":23},{"id":24,"end":96.06,"text":"はい。早く仕事を覚えたいと思います。","start":92.44,"sequenceId":24}]}', NULL, '2026-04-09T04:47:25.437+00:00', '2026-08-10T16:47:29.253+00:00');

